function skinIcon(s){
  if(SIG_SKIN_ICON[s.id])return svgWrap(SIG_SKIN_ICON[s.id]);
  return svgWrap("<rect x='15' y='4' width='10' height='9' rx='2' fill='"+hexStr(s.skin)+"'/>"+
    "<rect x='12' y='14' width='16' height='14' rx='3' fill='"+hexStr(s.body)+"'/>"+
    "<rect x='7' y='15' width='4' height='12' rx='2' fill='"+hexStr(s.body)+"'/>"+
    "<rect x='29' y='15' width='4' height='12' rx='2' fill='"+hexStr(s.body)+"'/>"+
    "<rect x='14' y='28' width='5' height='9' rx='2' fill='"+hexStr(s.limb)+"'/>"+
    "<rect x='21' y='28' width='5' height='9' rx='2' fill='"+hexStr(s.limb)+"'/>");
}
function swordIcon(s){
  var t=SWORD_ICON[s.shape]||SWORD_ICON.straight;
  return svgWrap(t.replace(/\{B\}/g,hexStr(s.blade)).replace(/\{H\}/g,hexStr(s.hilt))
    .replace(/\{G\}/g,hexStr(s.glow)));
}
function abilIcon(a,size){
  var t=ABIL_ICON[a.id]||ABIL_ICON.dash;
  return svgWrap(t.replace(/\{C\}/g,hexStr(a.color)),size);
}
function mapIcon(m){
  return svgWrap("<circle cx='20' cy='20' r='14' fill='"+hexStr(m.floor)+"' stroke='"+hexStr(m.accentA)+"' stroke-width='2.5'/>"+
    "<circle cx='20' cy='20' r='7' fill='none' stroke='"+hexStr(m.accentB)+"' stroke-width='1.6' opacity='.8'/>");
}
function rankIcon(r,size){
  return svgWrap("<path d='M20 3 L34 9 L34 21 C34 29 27 35 20 37 C13 35 6 29 6 21 L6 9 Z' fill='"+hexStr(r.color)+
    "' opacity='.92'/><path d='M20 3 L34 9 L34 21 C34 29 27 35 20 37 C13 35 6 29 6 21 L6 9 Z' fill='none' stroke='"+
    hexStr(r.edge)+"' stroke-width='2'/><text x='20' y='26' font-size='15' font-weight='bold' text-anchor='middle' fill='"+
    hexStr(r.edge)+"' font-family='Trebuchet MS,Arial'>"+r.glyph+"</text>",size);
}

