// some abilities are a guaranteed kill with only one opponent, so they sit out of 1v1
/* One on one there is nobody else for the ball to go to, so anything that
   takes you out of its reach -- untargetable, invisible, a decoy -- is just a
   free escape. Those sit out of every 1v1, solo or online. */
function isDuel(){
  if(!MODE||MODE.teams)return false;
  return MODE.net?!!MODE.duelNet:MODE.bots===1;
}
function abilityAllowed(id){
  var a=abilById(id);
  if(a.notReady)return false;
  if(a.hides&&isDuel())return false;
  if(!a.no1v1)return true;
  // These sit out of 1v1 because they are a guaranteed kill with one opponent.
  // In a party you are playing other people, so the whole roster is open.
  if(MODE.net)return true;
  return MODE.bots>1;
}
/* A slashed ball's path, drawn in sparks for a moment as it leaves, so whoever
   it is going for can see which way it will bend (Dark only shows the start). */
var _tellV=null;
function pathTell(b,upTo,c){
  if(!_tellV)_tellV=new THREE.Vector3();
  for(var i=1;i<=16;i++){var s2=upTo*i/16;curveAt(b,b.target,s2,_tellV);
    spark(_tellV.x,_tellV.y,_tellV.z,0,.2,0,c[0],c[1],c[2],.5,.55,0);}
}
/* Riposte: the blade rips the ground open along your aim */
var RIPOSTE={range:12,mult:0.85,arcY:14,len:11};
function riposteRift(f,aim){
  var sx=Math.sin(aim),sz=Math.cos(aim),n=10;
  for(var i=1;i<=n;i++){
    var d=RIPOSTE.len*i/n,x=f.pos.x+sx*d,z=f.pos.z+sz*d,w=(Math.random()-.5)*0.8;
    x+=sz*w;z-=sx*w;
    burst(x,0.3,z,8,4+i*0.3,i%2?0xff6a3c:0xffd0a0,1.1,.5,-6);
    spark(x,0.2,z,rr(-.4,.4),rr(3,7),rr(-.4,.4),1,.42,.2,.6,.6,14);
  }
  ringBurst(f.pos.x,0.3,f.pos.z,30,9,0xff6a3c,1.6,.6);
  ringBurst(f.pos.x,f.y+1.4,f.pos.z,24,6,0xffffff,1.3,.45);
}
/* Chrono Well: a field CHRONO.r across that follows its caster. A ball inside
   crawls at CHRONO.k of its pace (Brake's is half), and enemies inside wade. */
var CHRONO={dur:8,r:15,k:0.3,wade:0.55};
function chronoTick(f,t){
  var i,b,o,r2=CHRONO.r*CHRONO.r;
  for(i=0;i<balls.length;i++){b=balls[i];
    if(b.active&&dist2(b.pos.x,b.pos.z,f.pos.x,f.pos.z)<r2){b.slow=Math.max(b.slow||0,0.12);b.slowK=CHRONO.k;}}
  var all=livingFighters(false);
  for(i=0;i<all.length;i++){o=all[i];
    if(hostileTo(f,o)&&dist2(o.pos.x,o.pos.z,f.pos.x,f.pos.z)<r2){o.speedMul=Math.min(o.speedMul,CHRONO.wade);o.speedT=Math.max(o.speedT,0.15);}}
  if(!f.chronoFx){
    var g=new THREE.Group(),col=0xa35cff;
    var rim=new THREE.Mesh(GEO.armRing,new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:.8,side:THREE.DoubleSide,depthWrite:false,blending:THREE.AdditiveBlending}));
    var disc=new THREE.Mesh(new THREE.CircleGeometry(1,48),new THREE.MeshBasicMaterial({color:0x5a1aa8,transparent:true,opacity:.2,side:THREE.DoubleSide,depthWrite:false,blending:THREE.AdditiveBlending}));
    var inner=new THREE.Mesh(GEO.armRing,new THREE.MeshBasicMaterial({color:0xd8b8ff,transparent:true,opacity:.35,side:THREE.DoubleSide,depthWrite:false,blending:THREE.AdditiveBlending}));
    rim.rotation.x=disc.rotation.x=inner.rotation.x=-Math.PI/2;
    g.add(rim);g.add(disc);g.add(inner);g.userData.inner=inner;g.userData.rim=rim;
    scene.add(g);f.chronoFx=g;
  }
  var fx=f.chronoFx,k=Math.min(1,f.chronoT/1.0);
  fx.visible=true;fx.position.set(f.pos.x,0.07,f.pos.z);fx.scale.setScalar(CHRONO.r);
  fx.userData.rim.material.opacity=(0.55+0.3*Math.sin(t*6))*k;
  // a second ring sweeping inward, like a clock hand going round
  var ph=(t*0.6)%1;fx.userData.inner.scale.setScalar(1-ph*0.9);fx.userData.inner.material.opacity=0.4*k*(1-ph);
  if(QUAL>0&&Math.random()<0.5){var a2=Math.random()*TAU;spark(f.pos.x+Math.sin(a2)*CHRONO.r,0.3,f.pos.z+Math.cos(a2)*CHRONO.r,0,rr(.6,1.6),0,.64,.36,1,.5,.5,0);}
}
// down to the last two in any mode, it is a 1v1 now: what sits out of a 1v1 sits out
function lastTwoBan(a){
  if(!(a.no1v1||a.hides)||isDuel()||STATE!=="playing")return false;
  return livingFighters(false).length<=2;
}
function resolveAbility(id){return abilityAllowed(id)?id:"dash";}
// a bot's ability is rolled exactly like an ability chest: a mythic is as rare
// on a bot as it is for you to pull one
function botAbility(rnd){var it=rollItem("abil",rnd);return resolveAbility(it?it.id:"dash");}
