var TEX={};
var _glowTex=null;
// every sword flare, pillar halo, ball halo and the particle system used to make
// its own CanvasTexture from the same 64x64 image \u2014 that is ~30 GPU uploads of
// identical data. One shared texture instead.
function glowTex(){
  if(!_glowTex)_glowTex=mkTex(TEX.glow,1,1);
  return _glowTex;
}
/* ============================================================
   5a. THE ARENAS, 3.5 -- bigger, and built out properly
   Every arena is 30% wider than it was. Each one gets its own floor (stone,
   ice, basalt, marble, steel...) instead of the same grid in different
   colours, a painted centre and border, a raised rim with lights, an
   underside you can see from the edge, and a ring of scenery in its theme,
   some of it moving. Scenery is decoration only: it never touches play, and
   it is laid out from the map's own seed so an arena looks the same every
   time you get it.
   ============================================================ */
var ARENA_SCALE=1.3;
var ARENA_ANIM=[];
function seeded(str){
  var h=2166136261;
  for(var i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619);}
  return function(){h+=0x6D2B79F5;var t=h;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return ((t^t>>>14)>>>0)/4294967296;};
}
function rgbStr(hex,a){var c=hex2rgb(hex);return "rgba("+Math.round(c[0]*255)+","+Math.round(c[1]*255)+","+Math.round(c[2]*255)+","+(a===undefined?1:a)+")";}
function shade(hex,k){var c=hex2rgb(hex);return "rgb("+Math.round(clamp(c[0]*k,0,1)*255)+","+Math.round(clamp(c[1]*k,0,1)*255)+","+Math.round(clamp(c[2]*k,0,1)*255)+")";}

/* ---- the floor, one style per theme ---- */
var FLOOR_STYLE={shards:"slate",ice:"ice",magma:"basalt",grid:"grid",ruins:"sandstone",void:"obsidian",
  trees:"moss",dunes:"sand",temple:"marble",reactor:"steel"};
function floorCanvas(map){
  var S=512,c=cvs(S,S),x=c.getContext("2d"),R=seeded(map.id+"floor"),st=FLOOR_STYLE[map.deco]||"grid",i,j;
  function speck(n,a,b,cols,sz){for(var k=0;k<n;k++){x.fillStyle=cols[Math.floor(R()*cols.length)];x.globalAlpha=a+R()*(b-a);
    var s=sz*(0.5+R());x.fillRect(R()*S,R()*S,s,s);}x.globalAlpha=1;}
  function tiles(n,gap,col,edgeCol,jit){
    var w=S/n;
    for(i=0;i<n;i++)for(j=0;j<n;j++){
      var k=0.86+R()*0.22+(jit||0)*(R()-0.5);
      x.fillStyle=shade(col,k);x.fillRect(i*w+gap/2,j*w+gap/2,w-gap,w-gap);
      x.fillStyle=edgeCol;x.globalAlpha=.25;x.fillRect(i*w+gap/2,j*w+gap/2,w-gap,3);x.globalAlpha=1;
    }
  }
  function cracks(n,col,wid,len){
    x.strokeStyle=col;x.lineWidth=wid;x.lineCap="round";
    for(var k=0;k<n;k++){var px=R()*S,py=R()*S,a=R()*6.28;x.beginPath();x.moveTo(px,py);
      for(var s=0;s<5;s++){a+=(R()-0.5)*1.4;px+=Math.cos(a)*len*(0.5+R());py+=Math.sin(a)*len*(0.5+R());x.lineTo(px,py);}x.stroke();}
  }
  x.fillStyle=hexStr(map.floor);x.fillRect(0,0,S,S);
  if(st==="slate"){
    x.fillStyle=shade(map.floor,.55);x.fillRect(0,0,S,S);
    tiles(4,6,map.floor,"#fff",0.1);speck(900,.05,.18,["#fff","#000"],2);
    x.strokeStyle=rgbStr(map.line,.55);x.lineWidth=2;
    for(i=0;i<=4;i++){x.beginPath();x.moveTo(i*S/4,0);x.lineTo(i*S/4,S);x.stroke();x.beginPath();x.moveTo(0,i*S/4);x.lineTo(S,i*S/4);x.stroke();}
  } else if(st==="ice"){
    var g=x.createLinearGradient(0,0,S,S);g.addColorStop(0,shade(map.floor,1.25));g.addColorStop(1,shade(map.floor,.95));
    x.fillStyle=g;x.fillRect(0,0,S,S);
    speck(500,.08,.3,["#ffffff","#dff6ff"],3);cracks(26,"rgba(255,255,255,.55)",1.6,22);cracks(14,"rgba(120,180,220,.4)",1,30);
  } else if(st==="basalt"){
    x.fillStyle="#140a08";x.fillRect(0,0,S,S);
    var hw=64,hh=hw*0.866;
    for(j=-1;j<S/hh+1;j++)for(i=-1;i<S/(hw*1.5)+1;i++){
      var cx=i*hw*1.5,cy=j*hh*2+(i%2?hh:0);
      x.beginPath();for(var q=0;q<6;q++){var an=q*Math.PI/3;x.lineTo(cx+Math.cos(an)*(hw-5),cy+Math.sin(an)*(hw-5));}x.closePath();
      x.fillStyle=shade(map.floor,0.9+R()*0.4);x.fill();
    }
    x.shadowColor="#ff6a1a";x.shadowBlur=10;cracks(22,"rgba(255,110,30,.85)",2.2,18);x.shadowBlur=0;
    speck(600,.05,.2,["#000","#3a1a10"],3);
  } else if(st==="grid"){
    speck(1400,.1,.3,["#1b1440","#2a0a44","#0a1a33"],2);
    x.strokeStyle=rgbStr(map.line,.65);x.lineWidth=3;
    for(i=0;i<=S;i+=128){x.beginPath();x.moveTo(i,0);x.lineTo(i,S);x.stroke();x.beginPath();x.moveTo(0,i);x.lineTo(S,i);x.stroke();}
    x.strokeStyle=rgbStr(map.accentB,.22);x.lineWidth=1.5;
    for(i=64;i<S;i+=128){x.beginPath();x.moveTo(i,0);x.lineTo(i,S);x.stroke();x.beginPath();x.moveTo(0,i);x.lineTo(S,i);x.stroke();}
    x.fillStyle=rgbStr(map.line,.9);for(i=0;i<=S;i+=128)for(j=0;j<=S;j+=128){x.fillRect(i-3,j-3,6,6);}
  } else if(st==="sandstone"){
    x.fillStyle=shade(map.floor,.6);x.fillRect(0,0,S,S);
    var bh=S/6;
    for(j=0;j<6;j++){var off=(j%2)*bh;for(i=-1;i<4;i++){x.fillStyle=shade(map.floor,0.85+R()*0.3);
      x.fillRect(i*bh*2+off+3,j*bh+3,bh*2-6,bh-6);}}
    speck(1200,.05,.2,["#fff3d8","#4a3a22"],2);cracks(10,"rgba(60,40,20,.45)",1.4,14);
  } else if(st==="obsidian"){
    x.fillStyle="#08060e";x.fillRect(0,0,S,S);tiles(3,4,map.floor,"#b14aff",0.1);
    x.strokeStyle=rgbStr(map.line,.5);x.lineWidth=2;x.shadowColor=hexStr(map.line);x.shadowBlur=8;
    for(i=0;i<5;i++){var r0=20+R()*40,ox=R()*S,oy=R()*S;x.beginPath();x.arc(ox,oy,r0,0,6.28);x.stroke();
      x.beginPath();x.moveTo(ox-r0,oy);x.lineTo(ox+r0,oy);x.moveTo(ox,oy-r0);x.lineTo(ox,oy+r0);x.stroke();}
    x.shadowBlur=0;speck(500,.05,.15,["#6a3cff","#000"],2);
  } else if(st==="moss"){
    x.fillStyle="#1a2a14";x.fillRect(0,0,S,S);
    for(i=0;i<34;i++){var sx=R()*S,sy=R()*S,sr=30+R()*40;x.beginPath();
      for(var q2=0;q2<7;q2++){var a2=q2/7*6.28,rr2=sr*(0.75+R()*0.3);x.lineTo(sx+Math.cos(a2)*rr2,sy+Math.sin(a2)*rr2);}
      x.closePath();x.fillStyle=shade(0x5a6a50,0.8+R()*0.4);x.fill();}
    speck(1600,.15,.45,["#3a7028","#27461d","#8fe86a"],3);
  } else if(st==="sand"){
    var sg=x.createLinearGradient(0,0,0,S);sg.addColorStop(0,shade(map.floor,1.08));sg.addColorStop(1,shade(map.floor,.92));
    x.fillStyle=sg;x.fillRect(0,0,S,S);
    x.strokeStyle="rgba(120,80,30,.22)";x.lineWidth=3;
    for(j=0;j<S;j+=22){x.beginPath();for(i=0;i<=S;i+=16)x.lineTo(i,j+Math.sin(i*0.03+j*0.2)*6);x.stroke();}
    speck(1500,.08,.25,["#fff0c8","#8a6a3a"],2);
  } else if(st==="marble"){
    x.fillStyle="#e9edf5";x.fillRect(0,0,S,S);
    x.fillStyle="#cfd6e4";for(i=0;i<4;i++)for(j=0;j<4;j++)if((i+j)%2)x.fillRect(i*S/4,j*S/4,S/4,S/4);
    cracks(18,"rgba(120,130,160,.35)",1.3,26);
    x.strokeStyle="rgba(214,170,90,.9)";x.lineWidth=4;
    for(i=0;i<=4;i++){x.beginPath();x.moveTo(i*S/4,0);x.lineTo(i*S/4,S);x.stroke();x.beginPath();x.moveTo(0,i*S/4);x.lineTo(S,i*S/4);x.stroke();}
  } else if(st==="steel"){
    x.fillStyle="#141a1e";x.fillRect(0,0,S,S);
    tiles(4,5,0x2a343c,"#8fa",0.05);
    for(i=0;i<4;i++)for(j=0;j<4;j++){x.fillStyle="rgba(200,220,230,.5)";
      [[10,10],[S/4-14,10],[10,S/4-14],[S/4-14,S/4-14]].forEach(function(p){x.beginPath();x.arc(i*S/4+p[0]+2,j*S/4+p[1]+2,3,0,6.28);x.fill();});}
    x.strokeStyle="rgba(0,224,160,.55)";x.lineWidth=2;
    for(i=0;i<=4;i++){x.beginPath();x.moveTo(i*S/4,0);x.lineTo(i*S/4,S);x.stroke();}
    speck(700,.05,.15,["#fff","#000"],2);
  }
  return c;
}

/* ---- the big painted overlay: centre seal, rings, spokes, border ---- */
function arenaSealCanvas(map){
  var S=1024,c=cvs(S,S),x=c.getContext("2d"),m=S/2,A=hexStr(map.accentA),B=hexStr(map.accentB),L=hexStr(map.line),i;
  x.clearRect(0,0,S,S);
  // border band
  x.lineWidth=26;x.strokeStyle=rgbStr(map.accentA,.35);x.beginPath();x.arc(m,m,m-18,0,6.28);x.stroke();
  x.lineWidth=5;x.strokeStyle=rgbStr(map.line,.7);x.beginPath();x.arc(m,m,m-36,0,6.28);x.stroke();
  for(i=0;i<48;i++){var a=i/48*6.28;x.save();x.translate(m+Math.cos(a)*(m-18),m+Math.sin(a)*(m-18));x.rotate(a);
    x.fillStyle=i%2?rgbStr(map.accentB,.7):rgbStr(map.accentA,.8);x.fillRect(-4,-9,8,18);x.restore();}
  // rings
  [0.26,0.52,0.76].forEach(function(f,k){x.lineWidth=k===1?6:3;x.strokeStyle=k===1?rgbStr(map.accentB,.45):rgbStr(map.line,.4);
    x.beginPath();x.arc(m,m,m*f,0,6.28);x.stroke();});
  // spokes between the inner and outer rings
  x.lineWidth=3;x.strokeStyle=rgbStr(map.line,.28);
  for(i=0;i<8;i++){var s=i/8*6.28;x.beginPath();x.moveTo(m+Math.cos(s)*m*0.3,m+Math.sin(s)*m*0.3);x.lineTo(m+Math.cos(s)*m*0.74,m+Math.sin(s)*m*0.74);x.stroke();}
  // the seal in the middle
  var g=x.createRadialGradient(m,m,0,m,m,m*0.22);g.addColorStop(0,rgbStr(map.accentA,.45));g.addColorStop(1,rgbStr(map.accentA,0));
  x.fillStyle=g;x.beginPath();x.arc(m,m,m*0.22,0,6.28);x.fill();
  x.lineWidth=8;x.strokeStyle=A;x.beginPath();x.arc(m,m,m*0.17,0,6.28);x.stroke();
  x.lineWidth=3;x.strokeStyle=B;x.beginPath();x.arc(m,m,m*0.14,0,6.28);x.stroke();
  // a four-point star
  x.fillStyle=rgbStr(map.line,.8);x.beginPath();
  for(i=0;i<8;i++){var r=i%2?m*0.035:m*0.12,a3=i/8*6.28-Math.PI/2;x.lineTo(m+Math.cos(a3)*r,m+Math.sin(a3)*r);}
  x.closePath();x.fill();
  x.fillStyle=A;x.beginPath();x.arc(m,m,m*0.028,0,6.28);x.fill();
  return c;
}

/* ---- small builders ---- */
function aMesh(geo,mat,sx,sy,sz,x,y,z){var q=new THREE.Mesh(geo,mat);q.scale.set(sx,sy,sz);q.position.set(x,y,z);arena.add(q);return q;}
function aLam(col,opt){var o={color:col};if(opt)for(var k in opt)o[k]=opt[k];return new THREE.MeshLambertMaterial(o);}
function aBasic(col,op,add){return new THREE.MeshBasicMaterial({color:col,transparent:op!==undefined&&op<1||!!add,opacity:op===undefined?1:op,
  blending:add?THREE.AdditiveBlending:THREE.NormalBlending,depthWrite:!add});}
function aAnim(m,kind,speed,amp){ARENA_ANIM.push({m:m,kind:kind,s:speed||1,a:amp||1,y0:m.position.y,ph:Math.random()*6.28});return m;}
function aGlow(x,y,z,col,size){
  var h=new THREE.Mesh(GEO.plane,new THREE.MeshBasicMaterial({map:glowTex(),color:col,transparent:true,
    blending:THREE.AdditiveBlending,depthWrite:false}));
  h.userData.shared=true;h.userData.billboard=true;h.scale.setScalar(size||4);h.position.set(x,y,z);arena.add(h);BILLBOARDS.push(h);return h;
}
function windowTex(col,lit){
  var c=cvs(64,128),x=c.getContext("2d");x.fillStyle="#07060f";x.fillRect(0,0,64,128);
  for(var j=4;j<124;j+=8)for(var i=4;i<60;i+=10){if(Math.random()<lit){x.fillStyle=Math.random()<0.2?"#ffffff":col;x.globalAlpha=0.5+Math.random()*0.5;x.fillRect(i,j,6,4);}}
  x.globalAlpha=1;return c;
}
function updateArenaAnim(dt,t){
  for(var i=0;i<ARENA_ANIM.length;i++){
    var o=ARENA_ANIM[i],m=o.m;
    if(o.kind==="spin")m.rotation.y+=dt*o.s;
    else if(o.kind==="spinz")m.rotation.z+=dt*o.s;
    else if(o.kind==="bob")m.position.y=o.y0+Math.sin(t*o.s+o.ph)*o.a;
    else if(o.kind==="pulse"){m.material.opacity=0.35+0.35*Math.abs(Math.sin(t*o.s+o.ph));}
    else if(o.kind==="flicker"){m.scale.setScalar(o.a*(0.85+Math.random()*0.3));}
  }
}

/* ---- the shared structure every arena gets ---- */
function buildArenaFrame(map){
  var R=seeded(map.id+"frame"),i,a;
  // the painted seal lies just over the floor
  var seal=new THREE.Mesh(new THREE.CircleGeometry(ARENA_R-0.2,72),new THREE.MeshBasicMaterial({map:mkTex(arenaSealCanvas(map),1,1),
    transparent:true,depthWrite:false,fog:true}));
  seal.rotation.x=-Math.PI/2;seal.position.y=0.03;arena.add(seal);
  // a raised rim with a lip of light and lamps round it
  var rimMat=aLam(map.pillar);
  var rim=new THREE.Mesh(new THREE.TorusGeometry(ARENA_R+0.35,0.45,8,90),rimMat);
  rim.rotation.x=-Math.PI/2;rim.position.y=0.15;arena.add(rim);
  var lip=new THREE.Mesh(new THREE.TorusGeometry(ARENA_R+0.35,0.1,6,90),aBasic(map.accentA));
  lip.rotation.x=-Math.PI/2;lip.position.y=0.55;arena.add(lip);
  var lamps=QUAL>0?24:12;
  for(i=0;i<lamps;i++){
    a=i/lamps*TAU;var lx=Math.cos(a)*(ARENA_R+1.1),lz=Math.sin(a)*(ARENA_R+1.1);
    aMesh(GEO.box,rimMat,0.7,1.1,0.7,lx,0.55,lz);
    var bulb=aMesh(GEO.sphLo,aBasic(i%2?map.accentB:map.accentA),0.45,0.45,0.45,lx,1.25,lz);
    if(QUAL>0&&i%2===0)aGlow(lx,1.25,lz,i%2?map.accentB:map.accentA,3.2);
  }
  // the underside: rock, ice or machinery hanging below the platform
  var floating={shards:1,void:1,temple:1,ice:0,magma:0,grid:1,ruins:0,trees:0,dunes:0,reactor:1}[map.deco];
  var underCol={shards:0x2a2244,void:0x120e1c,temple:0x8d97ad,grid:0x120a24,reactor:0x222c34}[map.deco]||map.pillar;
  if(floating){
    var cone=new THREE.Mesh(new THREE.ConeGeometry(ARENA_R*0.97,ARENA_R*0.9,24,3),aLam(underCol,{flatShading:true}));
    cone.rotation.x=Math.PI;cone.position.y=-2.2-ARENA_R*0.45;arena.add(cone);
    for(i=0;i<14;i++){a=R()*TAU;var d=R()*ARENA_R*0.8,h=4+R()*10;
      var ch=aMesh(GEO.cone,aLam(underCol,{flatShading:true}),2+R()*4,h,2+R()*4,Math.cos(a)*d,-2.2-h/2-R()*ARENA_R*0.3,Math.sin(a)*d);
      ch.rotation.x=Math.PI;}
    if(map.deco==="reactor"||map.deco==="grid")
      for(i=0;i<10;i++){a=i/10*TAU;aMesh(GEO.box,aBasic(map.accentA),0.5,0.5,0.5,Math.cos(a)*ARENA_R*0.9,-3,Math.sin(a)*ARENA_R*0.9);}
  } else {
    // grounded arenas stand on a thick plinth
    var pl=new THREE.Mesh(new THREE.CylinderGeometry(ARENA_R*0.99,ARENA_R*1.06,7,64),aLam(shadeHex(map.floor,0.7)));
    pl.position.y=-5.5;arena.add(pl);
  }
}
function shadeHex(hex,k){var c=hex2rgb(hex);return (Math.round(clamp(c[0]*k,0,1)*255)<<16)|(Math.round(clamp(c[1]*k,0,1)*255)<<8)|Math.round(clamp(c[2]*k,0,1)*255);}

/* ---- scenery, by theme ---- */
function buildScenery(map){
  var R=seeded(map.id+"scene"),i,a,d,m,g,n=function(k){return QUAL>0?k:Math.ceil(k*0.55);};
  function around(minD,maxD){var aa=R()*TAU,dd=minD+R()*(maxD-minD);return {x:Math.cos(aa)*dd,z:Math.sin(aa)*dd,a:aa};}
  var E=ARENA_R;
  if(map.deco==="shards"){
    // floating islands with grass, little trees and crystals, gently bobbing
    for(i=0;i<n(9);i++){
      var p=around(E+22,E+80);g=new THREE.Group();
      var s=5+R()*7;
      var rock=new THREE.Mesh(GEO.cone,aLam(0x3a2f5a,{flatShading:true}));rock.scale.set(s*2,s*1.8,s*2);rock.rotation.x=Math.PI;rock.position.y=-s*0.9;g.add(rock);
      var top=new THREE.Mesh(GEO.cyl8,aLam(0x3f8a4a));top.scale.set(s*2,0.8,s*2);g.add(top);
      if(R()<0.7){var tr=new THREE.Mesh(GEO.cyl8,aLam(0x5a4028));tr.scale.set(.6,3,.6);tr.position.set(s*0.3,1.9,0);g.add(tr);
        var cn=new THREE.Mesh(GEO.sphLo,aLam(0x2e7a3a));cn.scale.set(3,2.6,3);cn.position.set(s*0.3,4,0);g.add(cn);}
      var cr=new THREE.Mesh(GEO.cone,aBasic(map.accentA,.85));cr.scale.set(1,3.2,1);cr.position.set(-s*0.4,1.8,s*0.2);g.add(cr);
      g.position.set(p.x,-4+R()*22,p.z);arena.add(g);aAnim(g,"bob",0.4+R()*0.4,1.2+R());
    }
    for(i=0;i<n(14);i++){var q=around(E+40,E+150);var cl=aMesh(GEO.sphLo,aBasic(0xe8e4ff,.5),20+R()*30,5+R()*6,14+R()*20,q.x,-40-R()*30,q.z);}
  } else if(map.deco==="ice"){
    for(i=0;i<n(34);i++){
      var pp=around(E+10,E+90);g=new THREE.Group();
      var h=8+R()*10;
      var trk=new THREE.Mesh(GEO.cyl8,aLam(0x4a3626));trk.scale.set(.9,h*0.3,.9);trk.position.y=h*0.15;g.add(trk);
      for(var k=0;k<3;k++){var tier=new THREE.Mesh(GEO.cone,aLam(k===2?0xffffff:0x2d5a4a));tier.scale.set(h*(0.55-k*0.14),h*0.4,h*(0.55-k*0.14));
        tier.position.y=h*0.35+k*h*0.22;g.add(tier);}
      var cap=new THREE.Mesh(GEO.cone,aLam(0xffffff));cap.scale.set(h*0.28,h*0.2,h*0.28);cap.position.y=h*0.95;g.add(cap);
      g.position.set(pp.x,-5.5,pp.z);arena.add(g);
    }
    for(i=0;i<n(16);i++){var sm=around(E+6,E+70);aMesh(GEO.sphLo,aLam(0xf4fbff),8+R()*12,2+R()*3,6+R()*10,sm.x,-5.5,sm.z);}
    // the aurora: long soft ribbons, slowly shimmering
    var auc=cvs(256,64),ax=auc.getContext("2d"),ag=ax.createLinearGradient(0,0,0,64);
    ag.addColorStop(0,"rgba(120,255,200,0)");ag.addColorStop(.5,"rgba(120,255,200,.9)");ag.addColorStop(1,"rgba(120,120,255,0)");
    ax.fillStyle=ag;ax.fillRect(0,0,256,64);
    for(i=0;i<3;i++){var rib=new THREE.Mesh(new THREE.CylinderGeometry(180+i*30,180+i*30,40,40,1,true,0,Math.PI*0.9),
      new THREE.MeshBasicMaterial({map:mkTex(auc,1,1),transparent:true,opacity:.45,blending:THREE.AdditiveBlending,depthWrite:false,side:THREE.DoubleSide,fog:false}));
      rib.position.y=70+i*14;rib.rotation.y=i*1.1;arena.add(rib);aAnim(rib,"spin",0.02+i*0.01);aAnim(rib,"pulse",0.5+i*0.2);}
  } else if(map.deco==="magma"){
    // lava falls pouring off the cliffs, and a volcano glowing on the horizon
    var fc=cvs(32,256),fx=fc.getContext("2d"),fg=fx.createLinearGradient(0,0,0,256);
    fg.addColorStop(0,"#ffd23f");fg.addColorStop(.4,"#ff6a1a");fg.addColorStop(1,"rgba(255,40,0,.2)");fx.fillStyle=fg;fx.fillRect(0,0,32,256);
    for(i=0;i<n(10);i++){var lf=around(E+30,E+90);var fall=new THREE.Mesh(GEO.plane,new THREE.MeshBasicMaterial({map:mkTex(fc,1,1),transparent:true,side:THREE.DoubleSide,fog:false}));
      fall.scale.set(4+R()*5,40+R()*20,1);fall.position.set(lf.x,-4-fall.scale.y/2+18,lf.z);fall.rotation.y=-lf.a+Math.PI/2;arena.add(fall);
      aGlow(lf.x,-20,lf.z,0xff6a1a,24);}
    var vol=aMesh(GEO.cone,aLam(0x1a0806,{flatShading:true}),120,90,120,0,20,-260);
    aGlow(0,66,-260,0xff4a08,90);aGlow(0,60,-260,0xffd23f,40);
    for(i=0;i<n(18);i++){var em=around(E+4,E+40);aAnim(aGlow(em.x,1+R()*20,em.z,0xff7a2a,1.2+R()),"bob",0.6+R(),3);}
  } else if(map.deco==="grid"){
    // a neon city: towers with lit windows, and rings of light turning overhead
    var wins=[windowTex(hexStr(map.accentA),0.35),windowTex(hexStr(map.accentB),0.3),windowTex("#ffe45c",0.25)].map(function(cv){return mkTex(cv,1,1);});
    for(i=0;i<n(46);i++){
      var tp=around(E+36,E+170),th=30+R()*110,tw=10+R()*16;
      var tex=wins[i%3].clone();tex.needsUpdate=true;tex.repeat.set(Math.max(1,Math.round(tw/10)),Math.max(1,Math.round(th/16)));
      var tower=new THREE.Mesh(GEO.box,new THREE.MeshBasicMaterial({map:tex,color:0xffffff}));
      tower.scale.set(tw,th,tw);tower.position.set(tp.x,th/2-30,tp.z);arena.add(tower);
      var edge=aMesh(GEO.box,aBasic(i%2?map.accentA:map.accentB),tw+0.6,0.8,tw+0.6,tp.x,th-30,tp.z);
    }
    for(i=0;i<3;i++){var hr=new THREE.Mesh(new THREE.TorusGeometry(E*0.55+i*6,0.25,6,80),aBasic(i%2?map.accentB:map.accentA,.7,true));
      hr.position.y=22+i*5;hr.rotation.x=Math.PI/2+(R()-0.5)*0.3;arena.add(hr);aAnim(hr,"spinz",0.15*(i%2?-1:1));}
  } else if(map.deco==="ruins"){
    // tiered stands all the way round, with a crowd, banners and torches
    for(var t2=0;t2<4;t2++){
      var stand=new THREE.Mesh(new THREE.CylinderGeometry(E+14+t2*6,E+14+t2*6,3+t2*4,64,1,true),aLam(shadeHex(0xb49a72,1-t2*0.08),{side:THREE.DoubleSide}));
      stand.position.y=(3+t2*4)/2-1;arena.add(stand);
      var ledge=new THREE.Mesh(new THREE.TorusGeometry(E+14+t2*6,1.8,4,64),aLam(0x9a8460));ledge.rotation.x=-Math.PI/2;ledge.position.y=3+t2*4-1;arena.add(ledge);
      for(i=0;i<n(40);i++){var ca=R()*TAU,cd=E+14+t2*6+1.2;
        aMesh(GEO.box,aLam([0xc84a3a,0x3a6ac8,0xe8c84a,0x4ac86a,0xffffff][Math.floor(R()*5)]),1,1.6,1,Math.cos(ca)*cd,3+t2*4-0.2,Math.sin(ca)*cd);}
    }
    for(i=0;i<n(12);i++){a=i/12*TAU;var bx2=Math.cos(a)*(E+9),bz2=Math.sin(a)*(E+9);
      aMesh(GEO.cyl8,aLam(0x5a4028),0.5,14,0.5,bx2,6,bz2);
      var ban=aMesh(GEO.plane,new THREE.MeshLambertMaterial({color:i%2?map.accentA:map.accentB,side:THREE.DoubleSide}),3,6,1,bx2,10,bz2);ban.rotation.y=-a;
      if(i%3===0){aMesh(GEO.cyl8,aLam(0x3a3028),0.8,1.4,0.8,bx2,13.7,bz2);aAnim(aGlow(bx2,14.8,bz2,0xffa040,4),"flicker",1,4);}
    }
  } else if(map.deco==="void"){
    // a ring of runes turning overhead, shards orbiting, nebula in the dark
    var rc=cvs(1024,64),rx=rc.getContext("2d");rx.fillStyle="rgba(0,0,0,0)";rx.clearRect(0,0,1024,64);
    rx.font="bold 44px serif";rx.fillStyle=hexStr(map.accentA);rx.textBaseline="middle";
    var glyphs="ᚠᚢᚦᚨᚱᚲᚷᚹᚺᚾᛁᛃᛇᛈᛉᛊᛏᛒᛖᛗᛚᛜᛞᛟ";for(i=0;i<22;i++)rx.fillText(glyphs[i%glyphs.length],i*46+6,32);
    var rune=new THREE.Mesh(new THREE.CylinderGeometry(E*0.9,E*0.9,4,64,1,true),new THREE.MeshBasicMaterial({map:mkTex(rc,2,1),transparent:true,
      side:THREE.DoubleSide,blending:THREE.AdditiveBlending,depthWrite:false}));rune.position.y=26;arena.add(rune);aAnim(rune,"spin",0.12);
    for(i=0;i<n(16);i++){var sp=around(E+10,E+60);var sh=aMesh(GEO.box,aLam(0x2a1e44,{flatShading:true}),2+R()*4,2+R()*6,2+R()*4,sp.x,R()*30-8,sp.z);
      sh.rotation.set(R(),R(),R());aAnim(sh,"bob",0.3+R()*0.5,2);}
    for(i=0;i<n(6);i++){var nb=around(180,260);aGlow(nb.x,40+R()*120,nb.z,i%2?map.accentA:map.accentB,120+R()*120);}
  } else if(map.deco==="trees"){
    for(i=0;i<n(22);i++){var ff=around(E+2,E+40);aAnim(aGlow(ff.x,1+R()*6,ff.z,0xd8f06a,1.1),"bob",0.8+R(),1.5);}
    for(i=0;i<n(24);i++){var mu=around(E+3,E+30);
      aMesh(GEO.cyl8,aLam(0xf0e8d8),0.5,1.4,0.5,mu.x,-1.3,mu.z);
      aMesh(GEO.sphLo,aLam(R()<0.5?0xd84a3a:0x8a5ad8),1.8,0.9,1.8,mu.x,-0.5,mu.z);}
    for(i=0;i<n(18);i++){var rk=around(E+3,E+50);aMesh(GEO.sphLo,aLam(0x5a6258,{flatShading:true}),3+R()*5,2+R()*3,3+R()*5,rk.x,-2,rk.z);}
    aGlow(-140,160,-220,0xdfe8ff,90);aMesh(GEO.sph,aBasic(0xf4f6ff),40,40,40,-140,160,-222);
  } else if(map.deco==="dunes"){
    for(i=0;i<3;i++){var py=around(160,240);var pyr=aMesh(GEO.cone,aLam(0xd8b070,{flatShading:true}),90-i*18,70-i*14,90-i*18,py.x,27-i*7,py.z);
      pyr.rotation.y=Math.PI/4;}
    for(i=0;i<n(14);i++){var pm=around(E+8,E+60);g=new THREE.Group();
      var ph=9+R()*5,trunk=new THREE.Mesh(GEO.cyl8,aLam(0x8a6a3a));trunk.scale.set(.8,ph,.8);trunk.position.y=ph/2;trunk.rotation.z=(R()-0.5)*0.3;g.add(trunk);
      for(k=0;k<6;k++){var fr=new THREE.Mesh(GEO.box,aLam(0x3a8a2a));fr.scale.set(6,0.25,1.4);fr.position.set(Math.cos(k)*2.6,ph,Math.sin(k)*2.6);
        fr.rotation.set(0,-k,-0.35);g.add(fr);}
      g.position.set(pm.x,-7.5,pm.z);arena.add(g);}
    for(i=0;i<n(12);i++){var cc=around(E+6,E+50);aMesh(GEO.cyl8,aLam(0x4a8a3a),1.4,5+R()*4,1.4,cc.x,-6,cc.z);}
    aGlow(200,70,-260,0xfff0c0,160);
  } else if(map.deco==="temple"){
    // marble arches round the edge, statues, braziers, and a sea of cloud below
    for(i=0;i<8;i++){a=i/8*TAU+0.2;var ax2=Math.cos(a)*(E+8),az2=Math.sin(a)*(E+8),tx=-Math.sin(a)*4,tz=Math.cos(a)*4;
      aMesh(GEO.cyl8,aLam(0xe6ebf5),2,16,2,ax2+tx,7,az2+tz);aMesh(GEO.cyl8,aLam(0xe6ebf5),2,16,2,ax2-tx,7,az2-tz);
      var lint=aMesh(GEO.box,aLam(0xd6dcea),10.5,1.6,2.6,ax2,15.6,az2);lint.rotation.y=-a+Math.PI/2;
      aMesh(GEO.box,aBasic(0xffd8a0),10.6,0.3,2.7,ax2,16.5,az2).rotation.y=-a+Math.PI/2;
      if(i%2){aMesh(GEO.cyl8,aLam(0xc8a868),1.4,1.2,1.4,ax2,0.6,az2);aAnim(aGlow(ax2,2,az2,0xffb040,4),"flicker",1,4);}
    }
    for(i=0;i<n(24);i++){var cp=around(E+20,E+200);aMesh(GEO.sphLo,aBasic(0xf2f4ff,.85),30+R()*40,8+R()*8,20+R()*30,cp.x,-34-R()*10,cp.z);}
  } else if(map.deco==="reactor"){
    // pipes arching over, a catwalk, turning energy rings over the core
    for(i=0;i<n(6);i++){a=i/6*TAU;var pipe=new THREE.Mesh(new THREE.TorusGeometry(E+14,1.2,8,40,Math.PI*0.35),aLam(0x3a4650));
      pipe.rotation.set(0,a,0);pipe.position.y=-4;arena.add(pipe);}
    var cw=new THREE.Mesh(new THREE.TorusGeometry(E+9,1.4,4,72),aLam(0x2a343c));cw.rotation.x=-Math.PI/2;cw.position.y=-1;arena.add(cw);
    var cwl=new THREE.Mesh(new THREE.TorusGeometry(E+9,0.12,4,72),aBasic(0xffd23f));cwl.rotation.x=-Math.PI/2;cwl.position.y=0.5;arena.add(cwl);
    for(i=0;i<3;i++){var er=new THREE.Mesh(new THREE.TorusGeometry(7+i*3,0.35,6,48),aBasic(map.accentA,.8,true));
      er.position.y=30+i*2;er.rotation.x=Math.PI/2+i*0.5;arena.add(er);aAnim(er,"spinz",0.6*(i%2?-1:1));}
    aGlow(0,31,0,map.accentA,26);
    for(i=0;i<n(10);i++){var vp=around(E+5,E+30);aAnim(aGlow(vp.x,2,vp.z,0xc8fff0,5),"bob",0.5+R()*0.5,2);}
  }
}

function skyCanvas(map){
  var c=cvs(16,256),x=c.getContext("2d");
  var g=x.createLinearGradient(0,0,0,256);
  g.addColorStop(0,map.skyTop);g.addColorStop(.46,map.skyMid);g.addColorStop(1,map.skyBot);
  x.fillStyle=g;x.fillRect(0,0,16,256);
  return c;
}
function buildTextures(){
  var c=cvs(64,64),x=c.getContext("2d");
  var g=x.createRadialGradient(32,32,0,32,32,32);
  g.addColorStop(0,"rgba(255,255,255,1)");
  g.addColorStop(.32,"rgba(255,255,255,.55)");
  g.addColorStop(1,"rgba(255,255,255,0)");
  x.fillStyle=g;x.fillRect(0,0,64,64);
  TEX.glow=c;
  c=cvs(128,32);x=c.getContext("2d");
  var rg=x.createLinearGradient(0,0,0,32);
  rg.addColorStop(0,"rgba(255,255,255,0)");
  rg.addColorStop(.5,"rgba(255,255,255,1)");
  rg.addColorStop(1,"rgba(255,255,255,0)");
  x.fillStyle=rg;x.fillRect(0,0,128,32);
  for(var i=0;i<128;i+=16){x.fillStyle="rgba(255,255,255,.5)";x.fillRect(i,10,7,12);}
  TEX.band=c;
}
var GEO={},MAT={};
function initAssets(){
  GEO.box=new THREE.BoxGeometry(1,1,1);
  GEO.sph=new THREE.SphereGeometry(.5,16,12);
  GEO.sphLo=new THREE.SphereGeometry(.5,8,6);
  GEO.cyl=new THREE.CylinderGeometry(.5,.5,1,14);
  GEO.cyl8=new THREE.CylinderGeometry(.5,.5,1,8);
  GEO.cone=new THREE.ConeGeometry(.5,1,10);
  GEO.plane=new THREE.PlaneGeometry(1,1);
  GEO.ring=new THREE.RingGeometry(.62,1,28);
  GEO.armRing=new THREE.RingGeometry(.955,1,72);   // the catch range, drawn on the floor
  MAT.targetRing=new THREE.MeshBasicMaterial({color:0xff2020,transparent:true,opacity:.8,
    side:THREE.DoubleSide,depthWrite:false});
  MAT.shield=new THREE.MeshBasicMaterial({color:0xffd23f,transparent:true,opacity:.22,
    side:THREE.DoubleSide,depthWrite:false});
}

/* ============================================================
   5. ARENA + TERRAIN OBSTACLES
   ============================================================ */
var ARENA_R=34;
var arena=new THREE.Group();scene.add(arena);
var bandMat=null,ringMeshes=[],skyDome=null,CURMAP=MAPS[0];
var OBST=[];        // {x,z,r} cylinders fighters collide with (the ball ignores them)
var BILLBOARDS=[];  // cached, so the render loop never walks arena.children

function clearArena(){
  for(var i=arena.children.length-1;i>=0;i--){
    var o=arena.children[i];
    // the userData.shared flag alone was not enough: most of these are built
    // straight from GEO.box and friends without setting it, so every rebuild
    // was disposing the geometry the whole game draws with. disposeTree goes
    // all the way down and knows what is shared.
    disposeTree(o);
    arena.remove(o);
  }
  ringMeshes.length=0;OBST.length=0;BILLBOARDS.length=0;ARENA_ANIM.length=0;
}
function buildArena(map){
  CURMAP=map;
  sun.intensity=0.95;rimLight.intensity=0.45;
  renderer.toneMappingExposure=0.82;                 // Trick or Treat's night is not carried over
  ARENA_R=(map.r||34)*ARENA_SCALE;
  clearArena();
  if(!skyDome){
    skyDome=new THREE.Mesh(new THREE.SphereGeometry(500,22,16),
      new THREE.MeshBasicMaterial({side:THREE.BackSide,fog:false,depthWrite:false}));
    scene.add(skyDome);
  }
  if(skyDome.material.map&&skyDome.material.map.dispose)skyDome.material.map.dispose();
  skyDome.material.map=mkTex(skyCanvas(map),1,1);
  skyDome.material.needsUpdate=true;
  scene.fog.color.setHex(map.fog);
  renderer.setClearColor(map.fog,1);
  hemi.color.setHex(map.hemiSky);
  hemi.groundColor.setHex(map.hemiGnd);
  sun.color.setHex(map.sun);
  rimLight.color.setHex(map.accentB);

  var frep=Math.round(ARENA_R/6.5);
  var floorMat=new THREE.MeshLambertMaterial({map:mkTex(floorCanvas(map),frep,frep)});
  var disc=new THREE.Mesh(new THREE.CylinderGeometry(ARENA_R,ARENA_R*0.94,2.2,54),floorMat);
  disc.position.y=-1.1;disc.receiveShadow=true;arena.add(disc);
  var under=new THREE.Mesh(new THREE.ConeGeometry(ARENA_R*0.9,16,32,1,true),
    new THREE.MeshBasicMaterial({color:map.accentA,transparent:true,opacity:.13,
      side:THREE.BackSide,fog:false}));
  under.position.y=-10;under.rotation.x=Math.PI;arena.add(under);
  bandMat=new THREE.MeshBasicMaterial({map:mkTex(TEX.band,26,1),transparent:true,
    blending:THREE.AdditiveBlending,depthWrite:false,side:THREE.DoubleSide,color:map.accentA});
  var band=new THREE.Mesh(new THREE.CylinderGeometry(ARENA_R+.15,ARENA_R+.15,1.6,54,1,true),bandMat);
  band.position.y=.35;arena.add(band);
  for(var r=1;r<=3;r++){
    var rm=new THREE.Mesh(new THREE.TorusGeometry(ARENA_R*(r/4),0.09,6,50),
      new THREE.MeshBasicMaterial({color:r===2?map.accentB:map.accentA,transparent:true,opacity:.4}));
    rm.rotation.x=-Math.PI/2;rm.position.y=0.06;arena.add(rm);ringMeshes.push(rm);
  }

  var pillarMat=new THREE.MeshLambertMaterial({color:map.pillar});
  for(var i=0;i<12;i++){
    var a=(i/12)*TAU;
    var px=Math.cos(a)*(ARENA_R+3.2),pz=Math.sin(a)*(ARENA_R+3.2);
    var p=new THREE.Mesh(GEO.box,pillarMat);p.userData.shared=true;
    p.scale.set(2.2,rr(9,17),2.2);p.position.set(px,p.scale.y/2-1,pz);
    p.castShadow=QUAL>0;arena.add(p);
    var cap=new THREE.Mesh(GEO.sphLo,new THREE.MeshBasicMaterial({color:i%2?map.accentB:map.accentA}));
    cap.userData.shared=true;
    cap.scale.setScalar(1.5);cap.position.set(px,p.scale.y-1+.7,pz);arena.add(cap);
    var halo=new THREE.Mesh(GEO.plane,new THREE.MeshBasicMaterial({map:glowTex(),
      color:i%2?map.accentB:map.accentA,transparent:true,blending:THREE.AdditiveBlending,depthWrite:false}));
    halo.userData.shared=true;halo.userData.billboard=true;
    halo.scale.setScalar(9);halo.position.copy(cap.position);arena.add(halo);
    BILLBOARDS.push(halo);
  }
  buildDeco(map,pillarMat);
  buildObstacles(map);
  buildArenaFrame(map);
  buildScenery(map);
}
function addObstacle(x,z,r,mesh){
  OBST.push({x:x,z:z,r:r});
  if(mesh){mesh.castShadow=QUAL>0;mesh.receiveShadow=QUAL>0;arena.add(mesh);}
}
// a solid rectangle, hw by hd half-extents, turned rot about the vertical like a
// mesh's rotation.y: the shape of a stall or a shack, which a row of circles
// only ever roughly covered (you could walk into the corners and the back)
function addBoxObstacle(x,z,hw,hd,rot,top){
  OBST.push({x:x,z:z,r:Math.sqrt(hw*hw+hd*hd),hw:hw,hd:hd,rot:rot||0,top:top||5});
}
function pushOutObstacle(f,ob){
  var need=0.55,ddx=f.pos.x-ob.x,ddz=f.pos.z-ob.z;
  if(f.y>=(ob.top||5))return;
  if(!ob.hw){
    need+=ob.r;
    var dd=Math.sqrt(ddx*ddx+ddz*ddz);
    if(dd<need&&dd>0.0001){
      var ux=ddx/dd,uz=ddz/dd;
      f.pos.x=ob.x+ux*need;f.pos.z=ob.z+uz*need;
      var into=f.vel.x*ux+f.vel.z*uz;
      if(into<0){f.vel.x-=ux*into;f.vel.z-=uz*into;}
    }
    return;
  }
  if(ddx*ddx+ddz*ddz>(ob.r+need)*(ob.r+need))return;
  var c=Math.cos(ob.rot),s=Math.sin(ob.rot);
  var lx=ddx*c-ddz*s,lz=ddx*s+ddz*c;
  var cx=clamp(lx,-ob.hw,ob.hw),cz=clamp(lz,-ob.hd,ob.hd);
  var ex=lx-cx,ez=lz-cz,d=Math.sqrt(ex*ex+ez*ez),nx,nz;
  if(d>=need)return;
  if(d>0.0001){nx=ex/d;nz=ez/d;lx=cx+nx*need;lz=cz+nz*need;}
  else{
    // inside it: out through the nearest face
    var px=ob.hw-Math.abs(lx),pz=ob.hd-Math.abs(lz);
    if(px<pz){nx=lx<0?-1:1;nz=0;lx=nx*(ob.hw+need);}
    else{nx=0;nz=lz<0?-1:1;lz=nz*(ob.hd+need);}
  }
  f.pos.x=ob.x+lx*c+lz*s;f.pos.z=ob.z-lx*s+lz*c;
  var wx=nx*c+nz*s,wz=-nx*s+nz*c,into2=f.vel.x*wx+f.vel.z*wz;
  if(into2<0){f.vel.x-=wx*into2;f.vel.z-=wz*into2;}
}
function ringSpots(n,minR,maxR){
  var out=[];
  for(var i=0;i<n;i++){
    var a=(i/n)*TAU+rr(-.2,.2);
    var d=rr(minR,maxR);
    out.push({x:Math.cos(a)*d,z:Math.sin(a)*d});
  }
  return out;
}
function buildObstacles(map){
  var spots,i,m,s;
  if(map.obst==="spikes"){
    spots=ringSpots(7,10,ARENA_R*0.72);
    for(i=0;i<spots.length;i++){
      s=spots[i];
      m=new THREE.Mesh(GEO.cone,new THREE.MeshLambertMaterial({color:0xbfefff,transparent:true,opacity:.9}));
      var h=rr(5,9);
      m.scale.set(3.4,h,3.4);m.position.set(s.x,h/2,s.z);
      addObstacle(s.x,s.z,1.7,m);
    }
  } else if(map.obst==="rocks"){
    spots=ringSpots(8,9,ARENA_R*0.74);
    for(i=0;i<spots.length;i++){
      s=spots[i];
      m=new THREE.Mesh(GEO.sphLo,new THREE.MeshLambertMaterial({color:0x2a1810}));
      var sc=rr(3,4.6);
      m.scale.set(sc,sc*rr(.7,1.2),sc);m.position.set(s.x,sc*0.35,s.z);
      m.rotation.y=Math.random()*TAU;
      addObstacle(s.x,s.z,sc*0.48,m);
    }
  } else if(map.obst==="blocks"){
    spots=ringSpots(9,9,ARENA_R*0.76);
    for(i=0;i<spots.length;i++){
      s=spots[i];
      m=new THREE.Mesh(GEO.box,new THREE.MeshBasicMaterial({
        color:i%2?map.accentA:map.accentB,wireframe:true}));
      var w=rr(2.6,4.2);
      m.scale.set(w,rr(3,7),w);m.position.set(s.x,m.scale.y/2,s.z);
      m.rotation.y=rr(0,1);
      addObstacle(s.x,s.z,w*0.6,m);
    }
  } else if(map.obst==="columns"){
    spots=ringSpots(8,12,ARENA_R*0.78);
    for(i=0;i<spots.length;i++){
      s=spots[i];
      m=new THREE.Mesh(GEO.cyl8,new THREE.MeshLambertMaterial({color:0x8a7a5e}));
      m.scale.set(3.2,rr(6,13),3.2);m.position.set(s.x,m.scale.y/2,s.z);
      addObstacle(s.x,s.z,1.7,m);
    }
  } else if(map.obst==="trees"){
    spots=ringSpots(9,10,ARENA_R*0.76);
    for(i=0;i<spots.length;i++){
      s=spots[i];
      var g=new THREE.Group();
      var tr=new THREE.Mesh(GEO.cyl8,new THREE.MeshLambertMaterial({color:0x4a3624}));
      tr.scale.set(1.9,rr(8,12),1.9);tr.position.y=tr.scale.y/2;g.add(tr);
      for(var b=0;b<2;b++){
        var lf=new THREE.Mesh(GEO.sphLo,new THREE.MeshLambertMaterial({color:b?0x2e5a22:0x3a7028}));
        var ls=rr(5,8);
        lf.scale.set(ls,ls*.8,ls);lf.position.y=tr.scale.y+b*2.4-1;g.add(lf);
      }
      g.position.set(s.x,0,s.z);
      addObstacle(s.x,s.z,1.3,g);
    }
  } else if(map.obst==="spires"){
    spots=ringSpots(6,11,ARENA_R*0.72);
    for(i=0;i<spots.length;i++){
      s=spots[i];
      m=new THREE.Mesh(GEO.cone,new THREE.MeshLambertMaterial({color:0x9a7448}));
      var hh=rr(7,13);
      m.scale.set(rr(4,6),hh,rr(4,6));m.position.set(s.x,hh/2,s.z);
      addObstacle(s.x,s.z,2.2,m);
    }
  } else if(map.obst==="cores"){
    spots=ringSpots(6,10,ARENA_R*0.7);
    for(i=0;i<spots.length;i++){
      s=spots[i];
      var gg=new THREE.Group();
      var shell=new THREE.Mesh(GEO.cyl8,new THREE.MeshLambertMaterial({color:0x38424a}));
      shell.scale.set(3.4,7,3.4);shell.position.y=3.5;gg.add(shell);
      var core=new THREE.Mesh(GEO.cyl8,new THREE.MeshBasicMaterial({color:0x00e0a0}));
      core.scale.set(2.2,5.4,2.2);core.position.y=3.5;gg.add(core);
      gg.position.set(s.x,0,s.z);
      addObstacle(s.x,s.z,1.8,gg);
    }
  }
}
function buildDeco(map,pillarMat){
  var i,a,d,m;
  if(map.deco==="shards"||map.deco==="void"){
    for(i=0;i<22;i++){
      a=Math.random()*TAU;d=rr(60,150);
      m=new THREE.Mesh(GEO.box,pillarMat);m.userData.shared=true;
      m.scale.set(rr(3,13),rr(2,7),rr(3,13));
      m.position.set(Math.cos(a)*d,rr(-46,26),Math.sin(a)*d);
      m.rotation.set(rr(0,.5),Math.random()*TAU,rr(0,.5));
      arena.add(m);
    }
  } else if(map.deco==="ice"){
    var lake=new THREE.Mesh(new THREE.CylinderGeometry(300,300,1,32),
      new THREE.MeshLambertMaterial({color:0xcfe8f4}));
    lake.userData.shared=true;lake.position.y=-6;arena.add(lake);
    for(i=0;i<34;i++){
      a=Math.random()*TAU;d=rr(46,130);
      m=new THREE.Mesh(GEO.cone,new THREE.MeshLambertMaterial({color:0xbfefff,transparent:true,opacity:.85}));
      m.userData.shared=true;
      m.scale.set(rr(2,7),rr(6,22),rr(2,7));
      m.position.set(Math.cos(a)*d,m.scale.y/2-4,Math.sin(a)*d);
      arena.add(m);
    }
  } else if(map.deco==="magma"){
    var lava=new THREE.Mesh(new THREE.CylinderGeometry(300,300,1,32),
      new THREE.MeshBasicMaterial({color:0xff4a08}));
    lava.userData.shared=true;lava.position.y=-26;arena.add(lava);
    for(i=0;i<24;i++){
      a=Math.random()*TAU;d=rr(46,140);
      m=new THREE.Mesh(GEO.cone,new THREE.MeshLambertMaterial({color:0x2a1008}));
      m.userData.shared=true;
      m.scale.set(rr(6,20),rr(14,44),rr(6,20));
      m.position.set(Math.cos(a)*d,m.scale.y/2-24,Math.sin(a)*d);
      arena.add(m);
    }
  } else if(map.deco==="grid"){
    for(i=0;i<30;i++){
      a=Math.random()*TAU;d=rr(50,150);
      m=new THREE.Mesh(GEO.box,new THREE.MeshBasicMaterial({color:i%2?map.accentA:map.accentB,wireframe:true}));
      m.userData.shared=true;
      m.scale.set(rr(6,16),rr(10,40),rr(6,16));
      m.position.set(Math.cos(a)*d,rr(-30,20),Math.sin(a)*d);
      arena.add(m);
    }
  } else if(map.deco==="ruins"||map.deco==="temple"){
    var ground=new THREE.Mesh(new THREE.CylinderGeometry(320,320,1,32),
      new THREE.MeshLambertMaterial({color:map.deco==="temple"?0xb9c6e0:0xc8b48a}));
    ground.userData.shared=true;ground.position.y=map.deco==="temple"?-40:-12;arena.add(ground);
    for(i=0;i<32;i++){
      a=(i/32)*TAU;d=ARENA_R+rr(14,40);
      m=new THREE.Mesh(GEO.cyl8,new THREE.MeshLambertMaterial({color:map.deco==="temple"?0x8d97ad:0x8a7a5e}));
      m.userData.shared=true;
      m.scale.set(rr(2,4),rr(8,26),rr(2,4));
      m.position.set(Math.cos(a)*d,m.scale.y/2-9,Math.sin(a)*d);
      arena.add(m);
    }
  } else if(map.deco==="trees"){
    for(i=0;i<46;i++){
      a=Math.random()*TAU;d=rr(ARENA_R+8,150);
      var tg=new THREE.Group();tg.userData.shared=true;
      var tk=new THREE.Mesh(GEO.cyl8,new THREE.MeshLambertMaterial({color:0x3a2a1c}));
      tk.scale.set(2,rr(10,20),2);tk.position.y=tk.scale.y/2;tg.add(tk);
      var cn=new THREE.Mesh(GEO.sphLo,new THREE.MeshLambertMaterial({color:0x27461d}));
      var cs=rr(6,11);cn.scale.set(cs,cs*.85,cs);cn.position.y=tk.scale.y;tg.add(cn);
      tg.position.set(Math.cos(a)*d,-2,Math.sin(a)*d);arena.add(tg);
    }
  } else if(map.deco==="dunes"){
    var sand=new THREE.Mesh(new THREE.CylinderGeometry(360,360,1,32),
      new THREE.MeshLambertMaterial({color:0xd8b478}));
    sand.userData.shared=true;sand.position.y=-8;arena.add(sand);
    for(i=0;i<20;i++){
      a=Math.random()*TAU;d=rr(60,180);
      m=new THREE.Mesh(GEO.sphLo,new THREE.MeshLambertMaterial({color:0xcfa868}));
      m.userData.shared=true;
      m.scale.set(rr(30,70),rr(8,20),rr(30,70));
      m.position.set(Math.cos(a)*d,-6,Math.sin(a)*d);
      arena.add(m);
    }
  } else if(map.deco==="reactor"){
    for(i=0;i<26;i++){
      a=Math.random()*TAU;d=rr(44,130);
      m=new THREE.Mesh(GEO.box,new THREE.MeshLambertMaterial({color:0x222c34}));
      m.userData.shared=true;
      m.scale.set(rr(5,14),rr(14,46),rr(5,14));
      m.position.set(Math.cos(a)*d,m.scale.y/2-16,Math.sin(a)*d);
      arena.add(m);
      if(i%3===0){
        var glowM=new THREE.Mesh(GEO.box,new THREE.MeshBasicMaterial({color:0x00e0a0}));
        glowM.userData.shared=true;
        glowM.scale.set(m.scale.x*1.04,1.4,m.scale.z*1.04);
        glowM.position.set(m.position.x,m.position.y+m.scale.y*0.3,m.position.z);
        arena.add(glowM);
      }
    }
  }
}

/* ============================================================
   5b. VENUES \u2014 the lobby and the casino are walkable areas
   ============================================================ */
var venue=new THREE.Group();scene.add(venue);
var ZONES=[],VENUE_BB=[],venueKind=null;
function clearVenue(){
  for(var i=venue.children.length-1;i>=0;i--){
    var o=venue.children[i];
    disposeTree(o);
    venue.remove(o);
  }
  ZONES.length=0;VENUE_BB.length=0;OBST.length=0;
  VFX.length=0;SHOWCASE=null;
  if(typeof RANGE!=="undefined"){RANGE.on=false;RANGE.ball=null;RANGE.sign=null;}
  SHRINE=null;RODSHACK=null;
  renderer.toneMappingExposure=0.82;
}
// anything in a venue that animates registers itself here
var VFX=[],SHOWCASE=null;
function vAnim(mesh,kind,opts){
  var o=opts||{};o.m=mesh;o.kind=kind;VFX.push(o);return mesh;
}
// a flat additive panel \u2014 light shafts, glow discs, holograms
function vBeam(w,h,x,y,z,col,op,rot){
  var m=new THREE.Mesh(GEO.plane,new THREE.MeshBasicMaterial({color:col,
    transparent:true,opacity:op===undefined?.18:op,side:THREE.DoubleSide,
    blending:THREE.AdditiveBlending,depthWrite:false}));
  m.scale.set(w,h,1);m.position.set(x,y,z);
  if(rot)m.rotation.set(rot[0]||0,rot[1]||0,rot[2]||0);
  // a big additive plane close to the lens whites out the frame, so they fade
  // out as you approach instead of filling the screen
  m.userData.fadeNear=true;
  venue.add(m);return m;
}
function vRing(r,thick,x,y,z,col,op){
  var m=new THREE.Mesh(new THREE.TorusGeometry(r,thick,8,40),
    new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:op===undefined?.7:op,
      blending:THREE.AdditiveBlending,depthWrite:false}));
  m.position.set(x,y,z);m.rotation.x=-Math.PI/2;venue.add(m);return m;
}
function vBox(w,h,d,x,y,z,col,rot){
  var m=new THREE.Mesh(GEO.box,new THREE.MeshLambertMaterial({color:col}));
  m.scale.set(w,h,d);m.position.set(x,y,z);
  if(rot)m.rotation.set(rot[0]||0,rot[1]||0,rot[2]||0);
  m.castShadow=QUAL>0;m.receiveShadow=QUAL>0;venue.add(m);return m;
}
function vGlow(w,h,d,x,y,z,col){
  // transparent, so pulsing its opacity actually does something, and flagged
  // to fade out when the camera is right on top of it
  var m=new THREE.Mesh(GEO.box,new THREE.MeshBasicMaterial({color:col,
    transparent:true,opacity:1,depthWrite:true}));
  m.scale.set(w,h,d);m.position.set(x,y,z);
  m.userData.fadeNear=true;
  venue.add(m);return m;
}
// a big readable panel: dark plate, coloured bars, outlined text
function signCanvas(text,sub,col){
  var c=cvs(1024,256),g=c.getContext("2d");
  g.fillStyle="rgba(8,8,20,.88)";g.fillRect(0,0,1024,256);
  g.fillStyle=hexStr(col);
  g.fillRect(0,0,1024,14);g.fillRect(0,242,1024,14);
  g.fillRect(0,14,14,228);g.fillRect(1010,14,14,228);
  g.textAlign="center";
  g.font="bold 112px Fredoka, Trebuchet MS, Arial";
  g.lineWidth=12;g.strokeStyle="rgba(0,0,0,.85)";
  g.strokeText(text,512,sub?126:158);
  g.fillStyle="#ffffff";g.fillText(text,512,sub?126:158);
  if(sub){
    g.font="600 42px Fredoka, Trebuchet MS, Arial";
    g.lineWidth=7;g.strokeStyle="rgba(0,0,0,.8)";
    g.strokeText(sub,512,196);
    g.fillStyle=hexStr(col);g.fillText(sub,512,196);
  }
  return c;
}
function vLabel(text,sub,col,x,y,z,scale){
  var m=new THREE.Mesh(GEO.plane,new THREE.MeshBasicMaterial({map:mkTex(signCanvas(text,sub,col),1,1),
    transparent:true,depthWrite:false,fog:false}));
  var w=6.6*(scale||1);             // was 11: the floating signs filled half the screen
  m.scale.set(w,w*0.25,1);
  m.position.set(x,y,z);
  m.userData.billboard=true;
  m.userData.baseW=w;m.userData.baseH=w*0.25;
  VENUE_BB.push(m);
  venue.add(m);return m;
}
// the same text lying flat on the floor, so you read it as you walk up
function vFloorText(text,col,x,z,size){
  var c=cvs(1024,256),g=c.getContext("2d");
  g.textAlign="center";
  g.font="bold 150px Fredoka, Trebuchet MS, Arial";
  g.lineWidth=16;g.strokeStyle="rgba(0,0,0,.6)";g.strokeText(text,512,180);
  g.fillStyle=hexStr(col);g.globalAlpha=.85;g.fillText(text,512,180);
  var m=new THREE.Mesh(GEO.plane,new THREE.MeshBasicMaterial({map:mkTex(c,1,1),
    transparent:true,depthWrite:false}));
  m.rotation.x=-Math.PI/2;
  m.scale.set(size||11,(size||11)*0.25,1);
  m.position.set(x,0.42,z);
  venue.add(m);return m;
}
// a coloured lane from the middle of the room out to a zone, with chevrons
function vLane(x,z,col){
  var len=Math.sqrt(x*x+z*z);
  if(len<1)return;
  var ang=Math.atan2(x,z);
  var lane=new THREE.Mesh(GEO.plane,new THREE.MeshBasicMaterial({color:col,
    transparent:true,opacity:.16,depthWrite:false}));
  lane.rotation.x=-Math.PI/2;lane.rotation.z=-ang;
  lane.scale.set(3.4,len-4,1);
  lane.position.set(x*0.5*((len-4)/len),0.14,z*0.5*((len-4)/len));
  venue.add(lane);
  var n=Math.max(2,Math.floor((len-6)/3.4));
  for(var i=0;i<n;i++){
    var f=(i+1)/(n+1);
    var ch=new THREE.Mesh(GEO.cone,new THREE.MeshBasicMaterial({color:col,
      transparent:true,opacity:.5,depthWrite:false}));
    ch.scale.set(1.5,1.2,.5);
    ch.rotation.x=-Math.PI/2;ch.rotation.z=-ang+Math.PI;
    ch.position.set(x*f*0.82,0.2,z*f*0.82);
    venue.add(ch);
  }
}
// a sign on a post, so it reads as a real piece of wayfinding
function vPost(text,sub,col,x,z,height){
  height=height||11;
  var post=new THREE.Mesh(GEO.box,new THREE.MeshLambertMaterial({color:0x22203c}));
  post.scale.set(.5,height,.5);post.position.set(x,height/2,z);venue.add(post);
  var cap=new THREE.Mesh(GEO.box,new THREE.MeshBasicMaterial({color:col}));
  cap.scale.set(.9,.3,.9);cap.position.set(x,height+.15,z);venue.add(cap);
  return vLabel(text,sub,col,x,height+1.9,z,1);
}
function vPad(x,z,col,label,sub,action,opts){
  opts=opts||{};
  var pad=new THREE.Mesh(new THREE.CylinderGeometry(4.6,4.6,.34,26),
    new THREE.MeshLambertMaterial({color:col}));
  pad.position.set(x,.17,z);pad.receiveShadow=QUAL>0;venue.add(pad);
  var ring=new THREE.Mesh(new THREE.TorusGeometry(4.9,.16,8,30),
    new THREE.MeshBasicMaterial({color:col}));
  ring.rotation.x=-Math.PI/2;ring.position.set(x,.36,z);venue.add(ring);
  var beam=new THREE.Mesh(new THREE.CylinderGeometry(4.4,4.4,20,20,1,true),
    new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:.14,
      side:THREE.DoubleSide,depthWrite:false}));
  beam.position.set(x,10,z);venue.add(beam);
  if(opts.lane!==false)vLane(x,z,col);
  vFloorText(label,col,x,z,9);
  // the tall sign sits just behind the pad, facing the middle of the room
  var len=Math.sqrt(x*x+z*z)||1;
  var sx=x+(x/len)*5.6, sz=z+(z/len)*5.6;
  vPost(label,sub,col,sx,sz,opts.height||12);
  ZONES.push({x:x,z:z,r:5.0,label:label,action:action,ring:ring,beam:beam,col:col});
  return pad;
}
/* ---- Gnorman's stall: the Limited shop, standing in the lobby ----
   A market stall with a striped awning behind the podium, and the gnome who
   runs it. He watches you walk about, waves now and then, and the stall's
   floor ring is a zone like the pads: walk up and press F (or tap). */
function stallSign(){
  var c=cvs(1024,360),g=c.getContext("2d");
  function rr2(x,y,w,h,r){g.beginPath();if(g.roundRect)g.roundRect(x,y,w,h,r);else g.rect(x,y,w,h);}
  rr2(6,6,1012,348,56);g.fillStyle="#0b1942";g.fill();
  rr2(24,24,976,312,42);g.fillStyle="#e23aa8";g.fill();
  rr2(24,24,976,150,42);g.fillStyle="#ff6fd0";g.fill();
  g.textAlign="center";g.lineJoin="round";
  g.font="bold 168px Fredoka, Trebuchet MS, Arial";
  g.lineWidth=30;g.strokeStyle="#0b1942";g.strokeText("LIMITED",512,214);
  g.fillStyle="#ffffff";g.fillText("LIMITED",512,214);
  g.font="bold 56px Fredoka, Trebuchet MS, Arial";
  g.lineWidth=14;g.strokeText("GNORMAN'S STALL \u00b7 YEN ONLY",512,302);
  g.fillStyle="#ffe45c";g.fillText("GNORMAN'S STALL \u00b7 YEN ONLY",512,302);
  return c;
}
function gPart(parent,geo,col,sx,sy,sz,x,y,z){
  var m=new THREE.Mesh(geo,new THREE.MeshLambertMaterial({color:col}));
  m.scale.set(sx,sy,sz);m.position.set(x,y,z);
  m.castShadow=QUAL>0;parent.add(m);return m;
}
function buildGnome(){
  var gn=new THREE.Group();
  var BLUE=0x2f7df0,SKIN=0xffc9a3,WHITE=0xffffff;
  gPart(gn,GEO.cyl,BLUE,1.3,1.3,1.3,0,.65,0);                       // round body
  gPart(gn,GEO.cyl,0x6b3d17,1.36,.2,1.36,0,.5,0);                    // belt
  gPart(gn,GEO.box,0xffd23f,.26,.22,.08,0,.5,.68);                   // buckle
  gPart(gn,GEO.sph,SKIN,1,1,1,0,1.72,0);                             // head
  var beard=gPart(gn,GEO.cone,WHITE,1.25,1.15,1.05,0,1.18,.2);       // beard, point down
  beard.rotation.x=Math.PI;
  gPart(gn,GEO.sph,WHITE,.4,.26,.3,-.15,1.58,.42);                   // moustache
  gPart(gn,GEO.sph,WHITE,.4,.26,.3,.15,1.58,.42);
  gPart(gn,GEO.sph,0xff8a7a,.3,.3,.3,0,1.7,.5);                      // nose
  gPart(gn,GEO.sph,0x0b1942,.11,.11,.11,-.17,1.86,.42);             // eyes
  gPart(gn,GEO.sph,0x0b1942,.11,.11,.11,.17,1.86,.42);
  gPart(gn,GEO.box,WHITE,.2,.06,.06,-.17,1.97,.43);                  // brows
  gPart(gn,GEO.box,WHITE,.2,.06,.06,.17,1.97,.43);
  gPart(gn,GEO.cyl,0xff5a4a,1.26,.16,1.26,0,2.1,-.02);               // hat brim
  var hat=gPart(gn,GEO.cone,0xe8352b,1.2,1.7,1.2,-.04,2.95,-.06);    // tall hat
  hat.rotation.z=.12;
  gPart(gn,GEO.sph,0xffd23f,.3,.3,.3,-.14,3.78,-.06);                // pom
  var arms=[];
  for(var s=-1;s<=1;s+=2){
    var pv=new THREE.Group();pv.position.set(s*.64,1.22,0);gn.add(pv);
    gPart(pv,GEO.box,BLUE,.26,.72,.26,0,-.34,0);
    gPart(pv,GEO.sph,SKIN,.3,.3,.3,0,-.74,0);
    pv.rotation.z=s*.28;
    arms.push(pv);
  }
  gn.userData.armR=arms[1];
  return gn;
}
function buildStall(x,z){
  var st=new THREE.Group();st.position.set(x,0,z);venue.add(st);
  var WOOD=0x9a5f2c,DARK=0x6b3d17,PINK=0xff5cc8,CREAM=0xfff2fb,GOLD=0xffd23f;
  gPart(st,GEO.box,DARK,8.4,.3,4.6,0,.15,.3);                        // platform
  gPart(st,GEO.box,0x7a4a22,7.6,4.3,.35,0,2.3,-1.5);                 // back wall
  gPart(st,GEO.box,WOOD,7.2,1.35,1.3,0,.98,1.45);                    // counter
  gPart(st,GEO.box,0xc98a4a,7.7,.24,1.65,0,1.77,1.45);               // counter top
  gPart(st,GEO.box,PINK,6.8,.62,.06,0,1.02,2.13);                    // front panel
  gPart(st,GEO.box,GOLD,6.8,.1,.08,0,1.37,2.14);
  var i;
  for(i=0;i<4;i++)gPart(st,GEO.box,DARK,.3,4.7,.3,(i%2?1:-1)*3.62,2.5,i<2?2.1:-1.3);
  // the striped awning, sloping down towards the front
  for(i=0;i<8;i++){
    var sp=gPart(st,GEO.box,i%2?CREAM:PINK,1.0,.16,4.1,-3.5+i*1.0,4.95,.4);
    sp.rotation.x=-.2;
  }
  gPart(st,GEO.box,PINK,8.05,.5,.14,0,4.43,2.43);                    // valance
  gPart(st,GEO.box,GOLD,8.05,.1,.16,0,4.16,2.44);
  // the sign on the front of the awning
  var sign=new THREE.Mesh(GEO.plane,new THREE.MeshBasicMaterial({map:mkTex(stallSign(),1,1),
    transparent:true,depthWrite:false}));
  sign.scale.set(5.6,5.6*360/1024,1);sign.position.set(0,5.95,2.5);st.add(sign);
  // goods on the counter: two turning crystals and a little chest
  var cols=[0xff5cc8,0xffd23f];
  for(i=0;i<2;i++){
    var cr=new THREE.Mesh(new THREE.OctahedronGeometry(.36),new THREE.MeshLambertMaterial({color:cols[i],emissive:cols[i],emissiveIntensity:.35}));
    cr.position.set(i?2.7:-2.7,2.45,1.45);cr.scale.set(1,1.4,1);st.add(cr);
    vAnim(cr,"spin",{sp:1.4+i*.3});
    vAnim(cr,"bob",{y0:2.45,amp:.14,sp:2,ph:i*2});
  }
  var ch=gPart(st,GEO.box,0x3f97ff,.8,.5,.55,-1.55,2.14,1.45);
  gPart(ch,GEO.box,GOLD,1.04,.28,1.04,0,.12,0);
  ch.rotation.y=.35;
  gPart(st,GEO.box,0xb07cff,.5,.5,.5,1.5,2.14,1.5).rotation.y=-.5;
  // a crate to stand on, then the gnome himself
  gPart(st,GEO.box,DARK,1.3,.9,1.1,0,.75,.15);
  var gn=buildGnome();
  gn.position.set(0,1.2,.2);gn.scale.setScalar(1.05);st.add(gn);
  vAnim(gn,"gnome",{wx:x,wz:z+.2,arm:gn.userData.armR,yaw:0});
  // his floor ring: a zone like the pads
  var ring=vRing(2.8,.13,x,.32,z+4.3,PINK,.85);
  var disc=new THREE.Mesh(GEO.ring,new THREE.MeshBasicMaterial({color:PINK,transparent:true,opacity:.18,
    side:THREE.DoubleSide,depthWrite:false}));
  disc.rotation.x=-Math.PI/2;disc.position.set(x,.2,z+4.3);disc.scale.setScalar(2.8);venue.add(disc);
  vFloorText("LIMITED",PINK,x,z+7.6,6);
  ZONES.push({x:x,z:z+4.3,r:3.6,label:"GNORMAN'S STALL",action:function(){openLimited();},ring:ring,col:PINK});
  // the stall is solid: platform, counter and awning posts, corner to corner
  addBoxObstacle(x,z+.35,4.25,2.35,0,5.2);
  return st;
}
/* ---- THE LOBBY, HALLOWEEN ----
   Same room, same pads in the same places, dressed for the month: a harvest
   moon over an orange horizon, jack-o'-lanterns along the wall, gravestones,
   candles, bats and ground fog. It is wider than it was, so it has room for a
   target range on the right, Rodriga's shack behind where you come in and the
   Wendigo shrine beside Gnorman. */
var LOBBY_R=40;
var HW={ORANGE:0xff7a1a,PURPLE:0x8a3aff,GREEN:0x7aff5a,BONE:0xe8dcc4,STONE:0x3a3346,DARK:0x140a1c};
function hwBat(x,y,z){
  var g=new THREE.Group(),m=new THREE.MeshBasicMaterial({color:0x0a0410});
  var body=new THREE.Mesh(GEO.sphLo,m);body.scale.set(.35,.3,.45);g.add(body);
  var wings=[];
  for(var s=-1;s<=1;s+=2){
    var pv=new THREE.Group();pv.position.set(s*.12,0,0);g.add(pv);
    var w=new THREE.Mesh(GEO.cone,m);w.scale.set(.5,1.1,.08);w.rotation.z=-s*Math.PI/2;w.position.set(s*.5,0,0);pv.add(w);
    wings.push(pv);
  }
  var ey=new THREE.MeshBasicMaterial({color:0xff5a1a});
  for(var e=-1;e<=1;e+=2){var eye=new THREE.Mesh(GEO.sphLo,ey);eye.scale.setScalar(.07);eye.position.set(e*.08,.06,.2);g.add(eye);}
  g.position.set(x,y,z);g.userData.wings=wings;venue.add(g);return g;
}
function hwGrave(x,z,rot,s){
  s=s||1;
  var g=new THREE.Group();g.position.set(x,0,z);g.rotation.y=rot||0;venue.add(g);
  gPart(g,GEO.box,HW.STONE,1.3*s,1.7*s,.32*s,0,.85*s,0).rotation.z=rr(-.12,.12);
  gPart(g,GEO.cyl,HW.STONE,1.3*s,.32*s,1.3*s,0,1.7*s,0).rotation.x=Math.PI/2;
  gPart(g,GEO.box,0x5a4a6a,.62*s,.12*s,.34*s,0,1.35*s,0);     // the cross on its face
  gPart(g,GEO.box,0x5a4a6a,.12*s,.62*s,.34*s,0,1.3*s,0);
  gPart(g,GEO.box,0x241a14,1.5*s,.14*s,2.2*s,0,.07,.9*s);     // the grave itself
  return g;
}
function hwCandles(x,z,n){
  for(var i=0;i<n;i++){
    var a=rr(0,TAU),r=rr(0,.7),h=rr(.5,1.1),cx=x+Math.cos(a)*r,cz=z+Math.sin(a)*r;
    var c=vBox(.22,h,.22,cx,h/2,cz,0xf0e6d0);c.castShadow=false;
    var fl=vGlow(.16,.3,.16,cx,h+.2,cz,0xffb040);
    vAnim(fl,"flicker",{a:1,ph:rr(0,9)});
  }
}
function hwSky(){
  var c=cvs(16,256),x=c.getContext("2d");
  var g=x.createLinearGradient(0,0,0,256);
  g.addColorStop(0,"#07030f");g.addColorStop(.42,"#241036");g.addColorStop(.74,"#5a1a3a");g.addColorStop(.92,"#e0561a");g.addColorStop(1,"#ff8a2a");
  x.fillStyle=g;x.fillRect(0,0,16,256);
  return c;
}
function hwWeb(x,y,z,rot,s){
  var c=cvs(256,256),g=c.getContext("2d");
  g.strokeStyle="rgba(235,235,255,.55)";g.lineWidth=2;
  for(var k=0;k<7;k++){var a=k/6*Math.PI/2;g.beginPath();g.moveTo(0,0);g.lineTo(Math.cos(a)*256,Math.sin(a)*256);g.stroke();}
  for(var r=40;r<260;r+=42){g.beginPath();for(var k2=0;k2<=6;k2++){var a2=k2/6*Math.PI/2,rr2=r*(k2%2?0.9:1);
    if(k2===0)g.moveTo(Math.cos(a2)*rr2,Math.sin(a2)*rr2);else g.quadraticCurveTo(Math.cos(a2-.13)*rr2*.93,Math.sin(a2-.13)*rr2*.93,Math.cos(a2)*rr2,Math.sin(a2)*rr2);}g.stroke();}
  var m=new THREE.Mesh(GEO.plane,new THREE.MeshBasicMaterial({map:mkTex(c,1,1),transparent:true,depthWrite:false,side:THREE.DoubleSide}));
  m.scale.set(s,s,1);m.position.set(x,y,z);m.rotation.set(0,rot,0);venue.add(m);return m;
}
