function spawnVenuePlayer(x,z){
  player=new Fighter({name:"YOU",isPlayer:true,x:x,z:z,team:0,
    sword:SAVE.eqSword,ability:SAVE.eqAbil,skinDef:skinById(SAVE.eqSkin)});
  fighters.push(player);
  camYaw=Math.PI;camPitch=-0.14;camDist=prefCamDist();
  camLook.set(x,2.6,z);
  _aliveShown=-1;
}
var nearZone=null;
function updateVenue(dt,t){
  if(!player)return;
  updatePlayer(dt);
  player.update(dt,t);
  nearZone=null;
  var best=1e9;
  for(var i=0;i<ZONES.length;i++){
    var z=ZONES[i];
    var d=dist2(player.pos.x,player.pos.z,z.x,z.z);
    if(d<z.r*z.r&&d<best){best=d;nearZone=z;}
    if(z.ring){
      var on=(d<z.r*z.r);
      z.ring.material.opacity=1;
      z.ring.scale.setScalar(on?1.08+Math.sin(t*7)*0.05:1);
      if(z.beam){
        // the beam is a tall translucent cylinder; standing in it put the
        // camera INSIDE the geometry and hazed the entire screen
        var cd=Math.sqrt(dist2(z.x,z.z,camera.position.x,camera.position.z));
        z.beam.material.opacity=(on?0.3:0.12)*clamp((cd-1.5)/5,0,1);
      }
    }
  }
  var p=$("zonePrompt");
  var lbl=nearZone?nearZone.label:(RANGE.on&&RANGE.near&&RANGE.state==="idle"?"HIT THE BALL":null);
  if(lbl){
    if(hudC.zone!==lbl){$("zoneLabel").textContent=lbl;$("zoneKey").textContent=touchMode?"TAP":"F";hudC.zone=lbl;}
    p.classList.add("on");
  } else {p.classList.remove("on");hudC.zone=null;}
  for(i=0;i<VENUE_BB.length;i++){
    var bb=VENUE_BB[i];
    // face the camera's POSITION: turned to its yaw, every sign in the room
    // faced away from you -- culled, or mirrored where it was double-sided
    bb.rotation.y=Math.atan2(camera.position.x-bb.position.x,camera.position.z-bb.position.z);
    if(bb.userData.baseW){
      var dd=Math.sqrt(dist2(bb.position.x,bb.position.z,camera.position.x,camera.position.z));
      var k=1+clamp((dd-14)/46,0,0.75);       // keeps far signs legible
      bb.scale.set(bb.userData.baseW*k,bb.userData.baseH*k,1);
    }
  }
  updateVenueFX(dt,t);
  rangeTick(dt,t);shrineTick(dt,t);rodrigaTick(dt,t);
  $("vCoins").textContent=SAVE.coins.toLocaleString();
  $("vYen").textContent=SAVE.yen.toLocaleString();
}
function updateVenueFX(dt,t){
  // additive panels closer than a few metres are what caused the white-out
  for(var fi2=0;fi2<venue.children.length;fi2++){
    var fm=venue.children[fi2];
    if(!fm.userData.fadeNear||!fm.material)continue;
    var fd=Math.sqrt(dist2(fm.position.x,fm.position.z,camera.position.x,camera.position.z));
    fm.userData.nearK=clamp((fd-2.5)/6,0,1);
  }
  for(var i=0;i<VFX.length;i++){
    var v=VFX[i],m=v.m;
    if(v.kind==="spin")      m.rotation.y=t*v.sp;
    else if(v.kind==="spinz")m.rotation.z=t*v.sp;
    else if(v.kind==="bob")  m.position.y=v.y0+Math.sin(t*v.sp+(v.ph||0))*v.amp;
    else if(v.kind==="pulse")m.material.opacity=(v.lo+(v.hi-v.lo)*(0.5+0.5*Math.sin(t*v.sp+(v.ph||0))))
      *(m.userData.fadeNear?(m.userData.nearK===undefined?1:m.userData.nearK):1);
    else if(v.kind==="orbit"){
      var a=t*v.sp+(v.ph||0);
      m.position.set(Math.cos(a)*v.r,v.y0+Math.sin(t*1.3+(v.ph||0))*(v.amp||0),Math.sin(a)*v.r);
    } else if(v.kind==="gnome"){
      // Gnorman turns to watch you, breathes, and waves every few seconds
      if(player){
        var want=Math.atan2(player.pos.x-v.wx,player.pos.z-v.wz);
        want=clamp(want,-1.1,1.1);
        v.yaw+=(want-v.yaw)*Math.min(1,dt*3);
        m.rotation.y=v.yaw;
      }
      m.scale.y=1.05*(1+Math.sin(t*2.3)*.025);
      var wp=t%5.5;
      v.arm.rotation.z=wp<1.4?(2.5+Math.sin(wp*13)*.35):.28;
    } else if(v.kind==="flicker"){
      var fk=0.75+Math.random()*0.35+Math.sin(t*9+(v.ph||0))*0.1;
      m.scale.y=0.3*fk;m.material.opacity=0.65+0.35*fk;
    } else if(v.kind==="bat"){
      var ba=t*v.sp+v.ph;
      m.position.set(Math.cos(ba)*v.r,v.y0+Math.sin(t*1.7+v.ph)*1.4,Math.sin(ba)*v.r);
      m.rotation.y=-ba+(v.sp>0?0:Math.PI);
      var fl2=Math.sin(t*16+v.ph)*0.8,wg=m.userData.wings;
      if(wg){wg[0].rotation.z=fl2;wg[1].rotation.z=-fl2;}
    } else if(v.kind==="fog"){
      var fa=t*v.sp+v.ph;
      m.position.x=Math.cos(fa)*v.r;m.position.z=Math.sin(fa)*v.r;
      m.material.opacity=0.07+0.05*Math.sin(t*.5+v.ph);
    } else if(v.kind==="sweep"){
      m.rotation.y=t*v.sp;
      m.material.opacity=(v.lo+(v.hi-v.lo)*(0.5+0.5*Math.sin(t*v.sp*2)))
        *(m.userData.fadeNear?(m.userData.nearK===undefined?1:m.userData.nearK):1);
    }
  }
  // the showcase blade turns on its podium with its own aura running
  if(SHOWCASE){
    var sc=SHOWCASE;
    sc.mesh.rotation.y=t*0.55;
    sc.mesh.position.y=sc.y0+Math.sin(t*1.4)*0.22;
    sc.mesh.rotation.z=Math.sin(t*0.8)*0.07;
    if(sc.fx&&sc.fx.rate>0&&QUAL>0){
      sc.acc=(sc.acc||0)+sc.fx.rate*0.40*dt;
      while(sc.acc>=1){
        sc.acc-=1;
        var u=Math.random(),c=sc.fx.rainbow?hex2rgb(HSVHEX((t*.2+Math.random())%1))
                                          :fxLerpCol(sc.fx,Math.random());
        spark(sc.mesh.position.x+rr(-.3,.3),
              sc.mesh.position.y+u*2.6,
              sc.mesh.position.z+rr(-.3,.3),
              rr(-sc.fx.sp,sc.fx.sp),rr(sc.fx.vy[0],sc.fx.vy[1]),rr(-sc.fx.sp,sc.fx.sp),
              c[0],c[1],c[2],sc.fx.sz,sc.fx.life,sc.fx.g);
      }
    }
  }
  // slow motes drifting through the room so the air is never dead
  if(QUAL>0&&venueKind&&Math.random()<dt*(venueKind==="casino"?16:12)){
    var ma=Math.random()*TAU,mr=Math.sqrt(Math.random())*(ARENA_R-3);
    var mc2=venueKind==="casino"?[1,.55,.85]:[.55,.62,1];
    spark(Math.cos(ma)*mr,rr(0.2,1.5),Math.sin(ma)*mr,
      rr(-.08,.08),rr(.25,.75),rr(-.08,.08),mc2[0],mc2[1],mc2[2],
      rr(.28,.5),rr(3.5,6),0.02);
  }
}
function interact(){
  if(STATE!=="venue")return;
  if(!nearZone)return;
  sfx("coin");
  nearZone.action();
}

/* ============================================================
   6. PARTICLES
   ============================================================ */
var P={n:800,i:0};
function initParticles(){
  P.n=[760,1900,2800][QUAL===undefined?1:QUAL];
  var g=new THREE.BufferGeometry();
  P.pos=new Float32Array(P.n*3);P.col=new Float32Array(P.n*3);
  P.siz=new Float32Array(P.n);P.base=new Float32Array(P.n);
  P.life=new Float32Array(P.n);P.max=new Float32Array(P.n);
  P.vel=new Float32Array(P.n*3);P.grav=new Float32Array(P.n);
  for(var i=0;i<P.n;i++)P.pos[i*3+1]=-999;
  g.setAttribute("position",new THREE.BufferAttribute(P.pos,3));
  g.setAttribute("pcolor",new THREE.BufferAttribute(P.col,3));
  g.setAttribute("size",new THREE.BufferAttribute(P.siz,1));
  var m=new THREE.ShaderMaterial({
    uniforms:{map:{value:glowTex()},hres:{value:window.innerHeight*0.5}},
    vertexShader:["attribute float size;","attribute vec3 pcolor;","varying vec3 vC;","uniform float hres;",
      "void main(){vC=pcolor;vec4 mv=modelViewMatrix*vec4(position,1.0);",
      "gl_PointSize=max(1.0,size*hres/max(0.001,-mv.z));",
      "gl_Position=projectionMatrix*mv;}"].join("\n"),
    fragmentShader:["uniform sampler2D map;","varying vec3 vC;",
      "void main(){vec4 t=texture2D(map,gl_PointCoord);",
      "if(t.a<0.02)discard;gl_FragColor=vec4(vC*t.a,t.a);}"].join("\n"),
    transparent:true,depthWrite:false,blending:THREE.AdditiveBlending});
  P.pts=new THREE.Points(g,m);P.pts.frustumCulled=false;scene.add(P.pts);
}
function spark(x,y,z,vx,vy,vz,r,g,b,size,life,grav){
  var i=P.i;P.i=(P.i+1)%P.n;
  P.pos[i*3]=x;P.pos[i*3+1]=y;P.pos[i*3+2]=z;
  P.vel[i*3]=vx;P.vel[i*3+1]=vy;P.vel[i*3+2]=vz;
  P.col[i*3]=r;P.col[i*3+1]=g;P.col[i*3+2]=b;
  P.siz[i]=size;P.base[i]=size;P.life[i]=life;P.max[i]=life;
  P.grav[i]=grav===undefined?-11:grav;
}
function burst(x,y,z,n,spd,hex,size,life,grav){
  var c=hex2rgb(hex);
  for(var i=0;i<n;i++){
    var a=Math.random()*TAU,e=Math.random()*Math.PI-Math.PI/2;
    spark(x,y,z,Math.cos(a)*Math.cos(e)*spd*rr(.3,1),Math.sin(e)*spd*rr(.3,1)+spd*.25,
      Math.sin(a)*Math.cos(e)*spd*rr(.3,1),c[0],c[1],c[2],size,life*rr(.6,1.3),grav);
  }
}
/* ---- THE SLASH: a crescent of light thrown out by the strike ----
   Blade Ball's swing reads because of one shape: a thick crescent, white-hot
   along its outer edge and the blade's own colour through the middle, that
   whips round in front of the fighter in a few hundredths of a second and
   fades as it narrows to nothing. It is its own mesh, laid out in the plane
   each swing style cuts through, so a slash, an overhead and a spin each throw
   a different crescent. The strike also sends two faint rings across the floor. */
var SLASH={n:40,life:.26,reveal:.07,pool:[],rings:[]};
// span of the arc (radians), how far the cut plane tips from level, and size
var SLASH_STYLE={
  slash:   {span:3.9, tilt:.62, r:1.0,  w:1.0},
  uppercut:{span:3.2, tilt:-.95,r:.95,  w:1.0},
  overhead:{span:3.0, tilt:1.38,r:.95,  w:1.05},
  hammer:  {span:2.8, tilt:1.45,r:.9,   w:1.2},
  spin:    {span:6.1, tilt:.28, r:1.05, w:.85},
  twirl:   {span:5.0, tilt:.70, r:1.0,  w:.9},
  stab:    {span:1.2, tilt:.05, r:1.25, w:.7}
};
function slashMesh(){
  var S=SLASH.n,g=new THREE.BufferGeometry();
  var pos=new Float32Array(S*12),col=new Float32Array(S*12),idx=[];
  for(var i=0;i<S-1;i++)for(var b=0;b<3;b++){
    var a=i*4+b,c=(i+1)*4+b;
    idx.push(a,c,a+1, a+1,c,c+1);
  }
  g.setAttribute("position",new THREE.BufferAttribute(pos,3));
  g.setAttribute("color",new THREE.BufferAttribute(col,3));
  if(g.setIndex)g.setIndex(idx);
  var m=new THREE.Mesh(g,new THREE.MeshBasicMaterial({vertexColors:true,transparent:true,depthWrite:false,
    side:THREE.DoubleSide,blending:THREE.AdditiveBlending,toneMapped:false}));
  m.frustumCulled=false;m.visible=false;m.renderOrder=5;
  scene.add(m);
  return {mesh:m,pos:pos,col:col,t:-1};
}
function spawnSlash(f,stO,colO,rev){
  var r=null,i;
  for(i=0;i<SLASH.pool.length;i++)if(SLASH.pool[i].t<0){r=SLASH.pool[i];break;}
  if(!r){if(SLASH.pool.length>=12)return null;r=slashMesh();SLASH.pool.push(r);}
  var d=f.swordDef,st=stO||SLASH_STYLE[d.swing]||SLASH_STYLE.slash;
  var R=(2.6+Math.min(1.7,f.bladeReach||1)*.6)*st.r;
  var fx=Math.sin(f.yaw),fz=Math.cos(f.yaw);          // forward
  var rx=fz,rz=-fx;                                    // right
  var ct=Math.cos(st.tilt),s=Math.sin(st.tilt);
  // back: centre the arc behind the fighter so only its front part shows, as a
  // near-straight streak out in front (the Halloween weapons cut shapes with it)
  var bk=.3-(st.back||0);
  r.o=[f.pos.x+fx*bk,f.y+(st.tilt>1.2?2.2:1.85)+(st.dy||0),f.pos.z+fz*bk];
  r.u=[fx,0,fz];
  r.v=[rx*ct,s,rz*ct];                                 // the cut plane's sideways axis, tipped
  r.span=st.span;r.R=R;r.W=R*.46*st.w;
  r.rgb=hex2rgb(colO!==undefined?colO:d.glow);r.t=0;r.rev=!!rev;r.hot=!!st.hot;
  return r;
}
function slashRing(x,y,z,hex,delay,tilt){
  var r=null;
  for(var i=0;i<SLASH.rings.length;i++)if(SLASH.rings[i].t<0){r=SLASH.rings[i];break;}
  if(!r){
    if(SLASH.rings.length>=14)return;
    var m=new THREE.Mesh(new THREE.RingGeometry(.94,1,64),new THREE.MeshBasicMaterial({color:0xffffff,
      transparent:true,depthWrite:false,side:THREE.DoubleSide,blending:THREE.AdditiveBlending,toneMapped:false}));
    m.frustumCulled=false;m.visible=false;scene.add(m);
    r={mesh:m,t:-1};SLASH.rings.push(r);
  }
  r.mesh.position.set(x,y,z);
  r.mesh.rotation.set(-Math.PI/2+(tilt||0),0,0);
  r.mesh.material.color.setHex(hex);
  r.t=0;r.d=delay;
}
function updateSlashes(dt){
  var N=SLASH.n,i,j,v;
  if(HW_DEC.pool.length||HW_DEC.beams.length||HW_DEC.tears.length)hwDecalsTick(dt);
  if(HW_DEC.spikes)iceSpikesTick(dt);
  if(HW_DEC.skulls)wendigoSkullsTick(dt);
  if(HW_APP.length)hwApparitionsTick(dt);
  for(i=0;i<SLASH.pool.length;i++){
    var r=SLASH.pool[i];
    if(r.t<0)continue;
    r.t+=dt;
    if(r.t>=SLASH.life){r.t=-1;r.mesh.visible=false;continue;}
    var head=Math.min(1,r.t/SLASH.reveal);                     // how far round it has whipped
    var fade=Math.pow(1-clamp((r.t-SLASH.reveal*.6)/(SLASH.life-SLASH.reveal*.6),0,1),1.6);
    var thin=1-.75*clamp((r.t-SLASH.reveal)/(SLASH.life-SLASH.reveal),0,1);
    for(j=0;j<N;j++){
      var q=j/(N-1),t=q*head;                                  // 0 = where it began, head = the leading edge
      var a=r.span*(.5-t)*(r.rev?-1:1);                        // swept from the right round to the left (or back)
      var ca=Math.cos(a),sa=Math.sin(a);
      var dx=r.u[0]*ca+r.v[0]*sa,dy=r.u[1]*ca+r.v[1]*sa,dz=r.u[2]*ca+r.v[2]*sa;
      // fat in the middle, a point at each end
      var prof=Math.pow(Math.sin(Math.PI*q),.7)*thin;
      // across the band: clear inside, the blade's colour, a white-hot edge, a soft halo
      var rad=[r.R-r.W*prof,r.R-r.W*prof*.42,r.R+r.W*prof*.04,r.R+r.W*prof*.30];
      // brightest right behind the leading edge, trailing off behind it
      var br=fade*(.4+.6*Math.pow(q,1.3));
      for(v=0;v<4;v++){
        var o=j*12+v*3;
        r.pos[o]=r.o[0]+dx*rad[v];r.pos[o+1]=r.o[1]+dy*rad[v];r.pos[o+2]=r.o[2]+dz*rad[v];
        var c=r.hot?[0,1.5,2.0,0][v]:[0,1.1,1.5,0][v],wh=r.hot?[0,.04,.5,0][v]:[0,.12,.9,0][v];
        r.col[o]  =(r.rgb[0]*(1-wh)+wh)*c*br;
        r.col[o+1]=(r.rgb[1]*(1-wh)+wh)*c*br;
        r.col[o+2]=(r.rgb[2]*(1-wh)+wh)*c*br;
      }
    }
    var g=r.mesh.geometry;
    g.attributes.position.needsUpdate=true;g.attributes.color.needsUpdate=true;
    r.mesh.visible=true;
  }
  for(i=0;i<SLASH.rings.length;i++){
    var R=SLASH.rings[i];
    if(R.t<0)continue;
    R.t+=dt;
    var u=(R.t-R.d)/.45;
    if(u<0){R.mesh.visible=false;continue;}
    if(u>=1){R.t=-1;R.mesh.visible=false;continue;}
    var e=1-Math.pow(1-u,3);
    R.mesh.visible=true;
    R.mesh.scale.setScalar(1.4+e*4.6);
    R.mesh.material.opacity=.42*Math.pow(1-u,2);
  }
}
function clearSlashes(){
  hwDecalsClear();
  for(var i=0;i<SLASH.pool.length;i++){SLASH.pool[i].t=-1;SLASH.pool[i].mesh.visible=false;}
  for(i=0;i<SLASH.rings.length;i++){SLASH.rings[i].t=-1;SLASH.rings[i].mesh.visible=false;}
}
/* Blade Ball timing: the draw and the cut are over almost before you see them,
   then the weapon hangs in its follow-through and eases home. The choreography
   is unchanged; this only decides how fast each part of it plays. */
function swingWarp(p){
  if(p<.10)return p/.10*.30;
  if(p<.24)return .30+(p-.10)/.14*.44;
  if(p<.55)return .74+(p-.24)/.31*.16;
  return .90+(p-.55)/.45*.10;
}
// the strike itself: the crescent, the spray and the rings all land together
Fighter.prototype.strikeFx=function(){
  if(this._struck)return;
  this._struck=true;
  var d=this.swordDef,tip=this.swordTip();
  swingSweep(this);
  if(QUAL===0)return;
  burst(tip.x,tip.y,tip.z,QUAL>1?16:10,9,d.glow,1.05,.28,-5);
  var near=this===player||!player||dist2(this.pos.x,this.pos.z,player.pos.x,player.pos.z)<60*60;
  if(near){
    spawnSlash(this);
    slashRing(this.pos.x,this.y+1.25,this.pos.z,d.glow,0,.12);
    slashRing(this.pos.x,this.y+1.05,this.pos.z,d.glow,.07,-.08);
  }
  if(d.rarity==="legendary"||d.rarity==="mythic")
    ringBurst(tip.x,tip.y,tip.z,QUAL>1?24:14,11,d.glow,1.5,.5);
  if(d.swing==="hammer"||d.swing==="overhead")
    ringBurst(this.pos.x,this.y+.2,this.pos.z,QUAL>1?18:10,9,d.glow,1.4,.45);
};
/* A signature swing's first cut lands when a plain swing's does: a tenth of
   the way in. It used to play its wind-up at full length first, so the cut, its
   effects and its sound all came 0.1-0.3s after the press -- the block was on
   time, but everything you saw said you were late. The wind-up now happens in
   that first tenth, and the follow-through (and any later beats) fill the rest. */
var SIG_LEAD=0.10;
function sigWarp(p,w0){return p<SIG_LEAD?p/SIG_LEAD*w0:w0+(p-SIG_LEAD)/(1-SIG_LEAD)*(1-w0);}
Fighter.prototype.swingFrame=function(p,dt){
  var S=SIG_SWING[this.swordDef.swing];
  if(S){var w=sigWarp(p,S.beats[0].w);this._rawP=p;this.animateSwing(w);sigSwingFx(this,w);return;}
  var w=swingWarp(p);
  this.animateSwing(w);
  if(w>=.3)this.strikeFx();              // the instant the cut starts moving
};

function ringBurst(x,y,z,n,spd,hex,size,life){
  var c=hex2rgb(hex);
  for(var i=0;i<n;i++){
    var a=(i/n)*TAU;
    spark(x,y,z,Math.cos(a)*spd,rr(.4,1.8),Math.sin(a)*spd,c[0],c[1],c[2],size,life,-3);
  }
}
function updateParticles(dt){
  updateSlashes(dt);
  var p=P.pos,v=P.vel,l=P.life,s=P.siz,any=false;
  for(var i=0;i<P.n;i++){
    if(l[i]<=0){if(s[i]!==0){s[i]=0;p[i*3+1]=-999;any=true;}continue;}
    any=true;
    l[i]-=dt;
    v[i*3+1]+=P.grav[i]*dt;
    p[i*3]+=v[i*3]*dt;p[i*3+1]+=v[i*3+1]*dt;p[i*3+2]+=v[i*3+2]*dt;
    var f=l[i]/P.max[i];
    s[i]=P.base[i]*(0.3+f*0.7)*Math.min(1,f*3.4);
  }
  if(!any)return;                      // nothing alive: skip three buffer uploads
  P.pts.geometry.attributes.position.needsUpdate=true;
  P.pts.geometry.attributes.pcolor.needsUpdate=true;
  P.pts.geometry.attributes.size.needsUpdate=true;
}

