var _sigV=null;
// the per-frame life of each: a flickering candle, a burning neck and a lit
// head, runes turning
function sigSkinTick(f,dt,t){
  var s=f.sig,c,i,p;
  if(s.kind==="scarecrow"){
    var fl=.72+.28*Math.sin(t*13+f.phase)*Math.sin(t*7.3);
    s.glow.color.setRGB(1,.42*fl+.12,.06);
  } else if(s.kind==="horseman"){
    var fl2=.8+.2*Math.sin(t*11+f.phase);
    s.pk.userData.face.color.setRGB(1,.72*fl2+.1,.2*fl2);
    if(QUAL>0){
      var near=f===player?1:.35;
      f._neckAcc=(f._neckAcc||0)+dt*44*near*(QUAL>1?1:.6);
      var bp=f.mesh.position,yy=f.mesh.rotation.y;
      while(f._neckAcc>=1){f._neckAcc-=1;
        c=Math.random()<.5?[1,.45,.05]:[1,.8,.2];
        spark(bp.x+hr(-.16,.16),bp.y+2.85,bp.z+hr(-.16,.16),hr(-.3,.3),hr(1.4,3.2),hr(-.3,.3),c[0],c[1],c[2],hr(.55,.95),hr(.3,.55),3);
      }
      f._pkAcc=(f._pkAcc||0)+dt*14*near;
      if(f._pkAcc>=1&&s.pk.localToWorld){
        _sigV=_sigV||new THREE.Vector3();
        f.mesh.updateMatrixWorld(true);
        while(f._pkAcc>=1){f._pkAcc-=1;
          _sigV.set(0,.4,0);s.pk.localToWorld(_sigV);
          spark(_sigV.x+hr(-.1,.1),_sigV.y,_sigV.z+hr(-.1,.1),hr(-.2,.2),hr(.8,1.8),hr(-.2,.2),1,.6,.1,hr(.4,.7),hr(.25,.45),2);
        }
      }
    }
  } else if(SIG_TICK4[s.kind]){SIG_TICK4[s.kind](f,s,dt,t);
  } else if(s.kind==="hexwitch"){
    s.runes.rotation.y=t*1.3+f.phase;
    s.runes.position.y=2.1+Math.sin(t*2.1+f.phase)*.18;
    for(i=0;i<s.runes.children.length;i++)s.runes.children[i].rotation.y=t*3;
  }
}
