function buildRodrigaShack(x,z){
  var st=new THREE.Group();st.position.set(x,0,z);st.rotation.y=Math.atan2(-x,-z);venue.add(st);
  var WOOD=0x4a2e18,WOOD2=0x5e3a1e,DARK=0x241408,ROOF=0x2a1a2e,GLOW=0x7aff5a,i;
  gPart(st,GEO.box,DARK,13,.4,8,0,.2,-1);                            // porch
  gPart(st,GEO.box,WOOD,12,10.6,.5,0,5.4,-4.6).rotation.z=.02;       // back wall
  for(var sd=-1;sd<=1;sd+=2){
    gPart(st,GEO.box,WOOD2,.5,10,8,sd*6,5.2,-1).rotation.z=sd*.03;    // side walls, leaning
    for(i=0;i<5;i++)gPart(st,GEO.box,i%2?WOOD:WOOD2,.56,.3,8.1,sd*6,1.2+i*2,-1);
    // a crooked roof, one slab each side
    var rf=gPart(st,GEO.box,ROOF,7.6,.5,10,sd*3.4,11.9,-1);rf.rotation.z=-sd*.42;
    // posts at the front
    gPart(st,GEO.box,DARK,.5,10.4,.5,sd*5.6,5.2,2.8).rotation.z=sd*.04;
    // a skull on a post, and a green lantern
    gPart(st,GEO.cyl8,DARK,.22,3.2,.22,sd*7.8,1.6,3.8);
    gPart(st,GEO.sph,0xe8e0cc,.7,.62,.62,sd*7.8,3.5,3.8);
    var lan=vGlow(.5,.7,.5,0,0,0,GLOW);venue.remove(lan);st.add(lan);lan.position.set(sd*5.6,8,3.2);
    vAnim(lan,"flicker",{a:1,ph:sd*2});
  }
  gPart(st,GEO.box,DARK,12.6,.5,.5,0,10.4,2.8);                      // lintel
  var chim=gPart(st,GEO.box,0x3a2a2a,1.2,3.2,1.2,3.6,13.8,-3);chim.rotation.z=.15;
  var sign=new THREE.Mesh(GEO.plane,new THREE.MeshBasicMaterial({map:mkTex(rodSignCanvas(),1,1),transparent:true}));
  sign.scale.set(8,8*300/1024,1);sign.position.set(0,11.6,3.6);sign.rotation.x=-.12;st.add(sign);
  // shelves of jars along the back
  for(i=0;i<3;i++){gPart(st,GEO.box,WOOD2,10,.2,1,0,2.4+i*1.6,-4.0);
    for(var j=0;j<6;j++){var jc=[0x7aff5a,0xc86aff,0xff7a1a][(i+j)%3];
      var jar=new THREE.Mesh(GEO.cyl8,new THREE.MeshBasicMaterial({color:jc,transparent:true,opacity:.75}));
      jar.scale.set(.5,.7,.5);jar.position.set(-4+j*1.6,2.9+i*1.6,-4.0);st.add(jar);}}
  // Rodriga herself, behind her cauldron
  var rod=buildRodriga();rod.position.set(0,.4,-1.8);rod.scale.setScalar(1.8);st.add(rod);
  var caul=new THREE.Group();caul.position.set(0,0,1.6);st.add(caul);
  var pot=gPart(caul,GEO.sph,0x1a1a1e,3.2,2.4,3.2,0,1.4,0);
  var rim=new THREE.Mesh(new THREE.TorusGeometry(1.45,.22,8,28),new THREE.MeshLambertMaterial({color:0x2a2a30}));rim.rotation.x=Math.PI/2;rim.position.y=2.35;caul.add(rim);
  var brew=new THREE.Mesh(new THREE.CircleGeometry(1.4,28),new THREE.MeshBasicMaterial({color:GLOW}));brew.rotation.x=-Math.PI/2;brew.position.y=2.3;caul.add(brew);
  for(i=0;i<3;i++){var lg=gPart(caul,GEO.cyl8,0x1a1a1e,.2,1,.2,Math.cos(i*2.1)*1.2,.3,Math.sin(i*2.1)*1.2);lg.rotation.z=Math.cos(i*2.1)*.3;}
  var fire=vGlow(1.6,.5,1.6,0,0,0,0xff7a1a);venue.remove(fire);caul.add(fire);fire.position.y=.3;vAnim(fire,"flicker",{a:1,ph:1});
  var bubbles=[];
  for(i=0;i<6;i++){var bb=new THREE.Mesh(GEO.sphLo,new THREE.MeshBasicMaterial({color:0xb8ff9a,transparent:true,opacity:.9}));
    bb.scale.setScalar(.3);caul.add(bb);bubbles.push({m:bb,ph:Math.random()*3,a:Math.random()*TAU,r:Math.random()*1.1});}
  // the shack is solid; the cauldron too
  var rot=st.rotation.y;
  addBoxObstacle(x+Math.sin(rot)*-1,z+Math.cos(rot)*-1,6.3,4.2,rot,11);
  var cx=x+Math.sin(rot)*1.6,cz=z+Math.cos(rot)*1.6;
  addObstacle(cx,cz,1.9,null);
  // walk up to the cauldron and press F
  var fx=x+Math.sin(rot)*6.2,fz=z+Math.cos(rot)*6.2;
  var zr=vRing(3,.13,fx,.32,fz,GLOW,.85);
  ZONES.push({x:fx,z:fz,r:3.6,label:"RODRIGA'S SHACK",action:function(){openRodriga();},ring:zr,col:GLOW});
  vFloorText("RODRIGA",GLOW,fx+Math.sin(rot)*3.4,fz+Math.cos(rot)*3.4,6).rotation.z=rot;
  RODSHACK={x:x,z:z,rod:rod,st:st,caul:caul,bubbles:bubbles,brew:brew,chim:{x:x+Math.sin(rot)*-3+Math.cos(rot)*3.6,z:z+Math.cos(rot)*-3-Math.sin(rot)*3.6}};
}
function rodrigaTick(dt,t){
  if(!RODSHACK||venueKind!=="lobby")return;
  var R=RODSHACK,u=R.rod.userData;
  // she stirs, sways, and turns her head to watch you
  u.armL.rotation.x=-.5+Math.sin(t*1.6)*.35;u.armL.rotation.z=Math.cos(t*1.6)*.3;
  u.armR.rotation.z=-.3+Math.sin(t*.9)*.1;u.armR.rotation.x=(t%7<1.2)?-1.6+Math.sin(t*10)*.3:-.2;
  R.rod.position.y=.4+Math.sin(t*1.1)*.06;
  if(player){
    var wp=new THREE.Vector3();R.rod.getWorldPosition(wp);
    var want=Math.atan2(player.pos.x-wp.x,player.pos.z-wp.z)-R.st.rotation.y;
    while(want>Math.PI)want-=TAU;while(want<-Math.PI)want+=TAU;
    u.head.rotation.y+=(clamp(want,-.9,.9)-u.head.rotation.y)*Math.min(1,dt*2.5);
  }
  u.band.material.color.setHSL(.3,1,.45+.15*Math.sin(t*3));
  R.brew.material.color.setHSL(.3,1,.45+.1*Math.sin(t*2.3));
  for(var i=0;i<R.bubbles.length;i++){var b=R.bubbles[i],k=((t*.7+b.ph)%1);
    b.m.position.set(Math.cos(b.a+t*.3)*b.r,2.3+k*.5,Math.sin(b.a+t*.3)*b.r);b.m.scale.setScalar(.15+k*.3);b.m.material.opacity=1-k;}
  if(QUAL>0&&Math.random()<dt*10){
    var cp=new THREE.Vector3();R.caul.getWorldPosition(cp);
    spark(cp.x+rr(-1,1),2.8,cp.z+rr(-1,1),rr(-.3,.3),rr(1.5,3),rr(-.3,.3),.5,1,.35,rr(.6,1.1),rr(1,1.8),-.6);
    spark(R.chim.x+rr(-.3,.3),15.6,R.chim.z+rr(-.3,.3),rr(-.2,.2),rr(1,2),rr(-.2,.2),.45,.85,.35,rr(1,1.6),rr(1.6,2.6),-.4);
  }
}
var RODRIGA_SAY=["Heh heh heh. One token. That is the price.","Tokens do not grow on trees, dearie. They fall out of matches. Very, very rarely.",
  "Come back next month. I'll have something new bubbling.","You smell like someone who has never seen a Rodriga token."];
function openRodriga(){
  var off=rodrigaOffer(),tok=SAVE.tokens|0;
  var h="<div class='evtgrid'><div class='well evtpic rod'>"+RODRIGA_SVG+"<div class='bubble'>"+pick(RODRIGA_SAY)+"</div>"+
    "<ul class='gnomerules'><li>Paid with <b>Rodriga tokens</b> only</li><li>One item, and it changes every month</li>"+
    "<li>A token drops <b>1 in 10,000,000</b> matches, any mode</li></ul>"+
    "<div class='rodtok'>"+TOKEN_SVG+"<b>"+tok+"</b><span>TOKEN"+(tok===1?"":"S")+"</span></div></div><div class='well'>";
  if(!off)h+="<div class='dname'>NOTHING THIS MONTH</div><div class='ddesc'>Rodriga's cauldron is empty. Come back next month.</div>";
  else{
    var d=shopData(off.tab),own=!!d.own[off.it.id];
    h+=detailHead(off.it,d,off.tab,LIM_KIND[off.tab])+"<div class='dprice ol1'>1 RODRIGA TOKEN</div>";
    if(own)h+="<button class='big ghost' disabled>YOU OWN THIS</button>";
    else h+="<button class='big"+(tok>=1?"":" off")+"' id='evtBuy'>"+(tok>=1?"TRADE A TOKEN":"YOU NEED A TOKEN")+"</button>";
    var nx=new Date(Date.now()),left=Date.UTC(nx.getUTCFullYear(),nx.getUTCMonth()+1,1)-Date.now();
    h+="<div class='dnote'>This month's item. It leaves in "+evtLeft(left)+".</div>";
  }
  h+="</div></div>";
  evtShow("RODRIGA'S SHACK","hw",h);
  var b=$("evtBuy");
  if(b)b.addEventListener("click",function(){
    if((SAVE.tokens|0)<1){evtSay("You need a Rodriga token. They drop from matches, once in ten million.");sfx("tick");return;}
    function done(ok,why){
      if(!ok){evtSay(why);sfx("tick");return;}
      sfx("rank");var d2=shopData(off.tab);SAVE[d2.eq]=off.it.id;writeSave();refreshCoins();updateChips();updateLobbyBar();
      openRodriga();evtSay(off.it.name+" is yours. Heh heh heh.",true);
    }
    if(econOn()){
      if(b.disabled)return;b.disabled=true;
      econAct([{k:"rodriga"}],function(err,rs){var r0=rs&&rs[0];b.disabled=false;done(!err&&r0&&r0.ok,(r0&&r0.why)||econErr(err));});
      return;
    }
    var d3=shopData(off.tab);
    if(d3.own[off.it.id]){done(false,"You already own it.");return;}
    SAVE.tokens--;d3.own[off.it.id]=1;done(true);
  });
}
