/* ============================================================
   THE LOGIN CALENDAR
   Thirty days. Each day you play, the next square pays out -- missing a day
   never resets it -- and every tenth square is a free LEGENDARY+ spin.
   ============================================================ */
function loginToday(){return limDay();}
function loginLive(now){now=now||Date.now();return now>=LOGIN_CAL.from&&now<LOGIN_CAL.to;}
function loginState(){
  var L=SAVE.login;
  if(!L||typeof L!=="object")L=SAVE.login={id:"",n:0,last:""};
  if(L.id!==LOGIN_CAL.id){L.id=LOGIN_CAL.id;L.n=0;L.last="";}
  return L;
}
function loginCanClaim(){
  if(!loginLive())return false;
  var L=loginState();
  return L.n<LOGIN_CAL.rewards.length&&L.last!==loginToday();
}
function loginWhat(r){
  var out=[];
  if(r.L)out.push(r.L+" FREE LEGENDARY+ SPIN");
  if(r.c)out.push(r.c.toLocaleString()+" COINS");
  if(r.y)out.push(r.y.toLocaleString()+" YEN");
  if(r.s)out.push(r.s+" FREE SPIN"+(r.s>1?"S":""));
  return out.join(" + ");
}
function loginIcon(r){
  if(r.L)return "<svg viewBox='0 0 40 40'><path d='M7 18C7 9 33 9 33 18z' fill='#ffd23f' stroke='#0b1942' stroke-width='2.4' stroke-linejoin='round'/>"+
    "<rect x='7' y='18' width='26' height='15' rx='2.5' fill='#ff9a1a' stroke='#0b1942' stroke-width='2.4'/><rect x='7' y='16.5' width='26' height='4' fill='#fff3b0' stroke='#0b1942' stroke-width='2'/>"+
    "<path d='M20 21l2 4 4 .5-3 3 .8 4-3.8-2-3.8 2 .8-4-3-3 4-.5z' fill='#fff' stroke='#0b1942' stroke-width='1.2'/></svg>";
  if(r.s)return PASS_ICO.spin;
  if(r.y)return UI_ICO.YEN;
  return UI_ICO.COIN;
}
function loginGive(r){
  if(r.c)addCoins(r.c);
  if(r.y)addYen(r.y);
  if(r.s)SAVE.freeSpins=(SAVE.freeSpins|0)+r.s;
  if(r.L)SAVE.freeSpinsL=(SAVE.freeSpinsL|0)+r.L;
}
function openLogin(){
  var L=loginState(),live=loginLive(),can=loginCanClaim(),h="";
  var sub=!live?(Date.now()<LOGIN_CAL.from?"Starts on October 1.":"This calendar has finished."):
    (can?"Today's square is ready.":(L.n>=LOGIN_CAL.rewards.length?"All thirty claimed. Nice.":"Come back tomorrow for the next one."));
  h+="<div class='logsub'>"+sub+" Miss a day and nothing resets: the next square just waits for you. Every tenth is a <b>free LEGENDARY+ spin</b>.</div>";
  h+="<div class='loggrid'>";
  for(var i=0;i<LOGIN_CAL.rewards.length;i++){
    var r=LOGIN_CAL.rewards[i],got=i<L.n,now=(i===L.n&&can),big=!!r.L;
    h+="<div class='logday"+(got?" got":"")+(now?" now":"")+(big?" big":"")+"'><span class='ln'>DAY "+(i+1)+"</span>"+
      "<span class='li'>"+loginIcon(r)+"</span><span class='lw'>"+(r.L?"LEGENDARY+":r.c?r.c.toLocaleString():r.y?r.y+" ¥":r.s+" SPIN"+(r.s>1?"S":""))+"</span>"+
      (got?"<span class='lk'>"+UI_ICO.CHECK+"</span>":"")+"</div>";
  }
  h+="</div><div class='btnrow' style='justify-content:center;margin-top:10px'>"+
    "<button class='big gold"+(can?"":" off")+"' id='logClaim'>"+(can?"CLAIM DAY "+(L.n+1):"CLAIMED")+"</button></div>";
  evtShow(LOGIN_CAL.name,"gold",h);
  var b=$("logClaim");
  if(b&&can)b.addEventListener("click",function(){
    var r=LOGIN_CAL.rewards[L.n];
    function done(ok,why){
      if(!ok){evtSay(why);sfx("tick");return;}
      sfx("rank");refreshCoins();refreshLoginButton();openLogin();
      evtSay("DAY "+loginState().n+": "+loginWhat(r)+"!",true);
    }
    if(econOn()){
      if(b.disabled)return;b.disabled=true;
      econAct([{k:"login",day:loginToday()}],function(err,rs){var r0=rs&&rs[0];b.disabled=false;done(!err&&r0&&r0.ok,(r0&&r0.why)||econErr(err));});
      return;
    }
    if(!loginCanClaim()){done(false,"Already claimed today.");return;}
    L.n++;L.last=loginToday();loginGive(r);writeSave();done(true);
  });
}
function refreshLoginButton(){
  var b=$("lbLogin");if(!b)return;
  var show=loginLive()||Date.now()<LOGIN_CAL.from;
  b.classList.toggle("hide",!show);
  $("lbLoginN").textContent=loginCanClaim()?"!":String(Math.min(loginState().n,LOGIN_CAL.rewards.length));
  $("lbLoginN").classList.toggle("ready",loginCanClaim());
}
// the first time you reach the lobby each day, the calendar opens by itself
var LOGIN_SHOWN="";
function loginNudge(){
  if(!loginCanClaim()||LOGIN_SHOWN===loginToday())return;
  LOGIN_SHOWN=loginToday();
  setTimeout(function(){if(STATE==="venue"&&venueKind==="lobby"&&$("evt").classList.contains("hide"))openLogin();},900);
}


