// RICKY'S .9 -- matte black with gold trim: a long slide past the frame, a
// rectangular muzzle ringed in gold, gold serrations, trigger, sights and
// magazine plate. Held down at the side, raised and fired on a block.
// (Sword space: +y is the barrel, +z is "down" when it is levelled to shoot.)
SIG_SHAPE.pistol=function(g,seg,B,H,G){
  var i,black=v4Phong(0x141418,60),black2=new THREE.MeshLambertMaterial({color:0x1c1c22});
  var gold=v4Phong(0xd8a83a,130,0x4a3000,.55);
  function bx(m,w,h,d,x,y,z,rx){var o=new THREE.Mesh(GEO.box,m);o.scale.set(w,h,d);o.position.set(x,y,z);if(rx)o.rotation.x=rx;g.add(o);return o;}
  // the grip, in the fist, angled back a touch; stippled; gold base plate
  bx(black2,.26,.34,.62,0,-.08,.14,.22);
  bx(gold,.28,.3,.08,0,-.13,.47,.22);
  for(i=0;i<4;i++)bx(black,.27,.03,.5,0,-.18+i*.08,.14,.22);
  // frame and trigger guard under the slide
  bx(black,.26,.62,.18,0,.18,-.16);
  var tg=new THREE.Mesh(new THREE.TorusGeometry(.13,.028,6,14,Math.PI),black);tg.position.set(0,.2,.02);tg.rotation.y=Math.PI/2;tg.rotation.z=Math.PI/2;g.add(tg);
  var tr=bx(gold,.05,.05,.16,0,.2,.02,.3);
  // the long slide: the "blade", which glows
  var sl=seg(.3,2.9,.3,1.2,-.36,black);sl.userData.core=true;
  // gold edges running its length
  for(var sx=-1;sx<=1;sx+=2)bx(gold,.03,2.9,.03,sx*.15,1.2,-.51);
  // serrations at the back
  for(i=0;i<5;i++)bx(gold,.31,.04,.2,0,-.12+i*.08,-.36);
  // sights
  bx(black,.14,.1,.1,0,2.55,-.56);bx(gold,.05,.05,.04,0,2.55,-.62);
  bx(black,.16,.08,.12,0,-.18,-.56);
  // the muzzle: a gold rectangle round a dark bore
  var rim=new THREE.Mesh(GEO.box,gold);rim.scale.set(.34,.05,.34);rim.position.set(0,2.66,-.36);g.add(rim);
  bx(new THREE.MeshBasicMaterial({color:0x050505}),.18,.06,.18,0,2.68,-.36);
  var hot=new THREE.Mesh(GEO.sphLo,v4Add(0xffb040,.55));hot.scale.setScalar(.22);hot.position.set(0,2.78,-.36);hot.userData.aura=true;g.add(hot);
  g.userData.pulse=hot;g.userData.flareMul=.45;
  B.emissiveIntensity=.08;
  return 2.8;
};

// DIVINE RIGHT -- a silver-blue blade with a rune channel lit cyan, barbed
