  var orb=new THREE.Mesh(GEO.sph,orbM);orb.scale.setScalar(.5);orb.position.y=1.12;g.add(orb);
  var star=new THREE.Group();star.position.y=1.12;star.userData.aura=true;g.add(star);
  for(i=0;i<4;i++){var s=new THREE.Mesh(GEO.cone,new THREE.MeshBasicMaterial({color:0xffffff}));s.scale.set(.06,.26,.03);s.rotation.z=i*Math.PI/2;s.position.set(Math.sin(i*Math.PI/2)*.12,Math.cos(i*Math.PI/2)*.12,.26);star.add(s);}
  // gold barbs off the guard
  for(var sd=-1;sd<=1;sd+=2){var bb=new THREE.Mesh(GEO.cone,gold);bb.scale.set(.08,.44,.08);bb.position.set(sd*.34,1.4,0);bb.rotation.z=-sd*.5;g.add(bb);
    var bb2=new THREE.Mesh(GEO.cone,gold);bb2.scale.set(.07,.36,.07);bb2.position.set(sd*.3,.86,0);bb2.rotation.z=sd*(Math.PI-.6);g.add(bb2);}
  // the wings: a gold spine sweeping out and up, feathers hanging off it
