  for(sd=-1;sd<=1;sd+=2){var nb=new THREE.Mesh(GEO.cone,B);nb.scale.set(.06,.24,.05);nb.position.set(sd*.14,4.95,0);nb.rotation.z=-sd*.7;g.add(nb);}
  g.userData.pulse=orb;g.userData.flareMul=1.1;
