// a hanging weapon swings on its cord, and the Apex's fragments drift
function v4SwordIdle(f,sw,t,dt){
  var dg=sw.userData.dangle;
  if(dg){
    // it lags behind the way you are moving, and the swing flings it
    var sp=Math.hypot(f.vel.x,f.vel.z),sw2=f.swingT>0?Math.sin((1-f.swingT/Math.max(.01,f.swingDur))*Math.PI):0;
    dg.rotation.x=Math.sin(t*2.6+f.phase)*.18+clamp(sp*.012,0,.5)+sw2*.9;
    dg.rotation.z=Math.sin(t*1.9+f.phase)*.14;
    if(QUAL>0&&Math.random()<dt*(f===player?6:1.5)){
      f.mesh.updateMatrixWorld(true);var v=_v4v||(_v4v=new THREE.Vector3());v.set(0,1.5,0);dg.localToWorld(v);
      spark(v.x,v.y,v.z,0,-.5,0,.8,.05,.1,.34,.9,9);
      // and a drop left on the floor behind you as you walk
      if(sp>3&&Math.random()<.5)spark(v.x,.06,v.z,0,0,0,.45,.02,.04,.5,2.4,0);
    }
  }
  var fa=sw.userData.fetusAura;
  if(fa&&camera){fa.lookAt(camera.position);fa.material.opacity=.35+.15*Math.sin(t*3+f.phase);}
  if(sw.userData.fetusHalo)sw.userData.fetusHalo.rotation.y=t*1.4;
  var fr=sw.userData.frags;
  if(fr)for(var i=0;i<fr.children.length;i++){var m=fr.children[i],b=m.userData.base;
    m.position.set(b[0]+Math.sin(t*1.3+i)*.06,b[1]+Math.sin(t*1.7+i*1.3)*.12,b[2]);m.rotation.y=t*2+i;}
  var wg=sw.userData.wings;
  // folded close while it is sheathed, thrown open on the draw
  if(wg){var op=f.swingT>0?1:0;wg.userData.o=(wg.userData.o||0)+(op-(wg.userData.o||0))*Math.min(1,dt*(op?14:4));
    var o=wg.userData.o;wg.scale.set(.45+.55*o,(.5+.5*o)*(1+Math.sin(t*1.4)*.04),1);}
  var rn=sw.userData.runes;
  if(rn)rn.material.color.setHSL(.53,1,.62+.18*Math.sin(t*3)+(f.swingT>0?.2:0));
}
