// the #1's crown: it floats over whoever holds Apex, for everyone to see
function apexCrown(f){
  if(f._apexCrown){if(f._apexCrown.parent)f._apexCrown.parent.remove(f._apexCrown);disposeTree(f._apexCrown);f._apexCrown=null;}
  if(!f.swordDef||!f.swordDef.top1||!f.mesh)return;
  var c=new THREE.Group(),gold=v4Phong(0xffd23f,140,0x6a4400,.6),gem=new THREE.MeshBasicMaterial({color:0xfff4d0});
  var band=new THREE.Mesh(new THREE.TorusGeometry(.42,.07,6,20),gold);band.rotation.x=Math.PI/2;c.add(band);
  for(var i=0;i<5;i++){var a=i/5*TAU,sp=new THREE.Mesh(GEO.cone,gold);sp.scale.set(.12,.34,.12);sp.position.set(Math.cos(a)*.42,.18,Math.sin(a)*.42);c.add(sp);
    var g2=new THREE.Mesh(new THREE.OctahedronGeometry(.06),gem);g2.position.set(Math.cos(a)*.42,.4,Math.sin(a)*.42);c.add(g2);}
  var glow=new THREE.Mesh(GEO.plane,new THREE.MeshBasicMaterial({map:glowTex(),color:0xffd27a,transparent:true,opacity:.5,blending:THREE.AdditiveBlending,depthWrite:false}));
  glow.scale.setScalar(1.8);glow.userData.aura=true;glow.userData.bill=true;c.add(glow);
  c.position.y=4.25;c.userData.glow=glow;f.mesh.add(c);f._apexCrown=c;
}
function apexCrownTick(f,t){
  var c=f._apexCrown;if(!c)return;
  c.rotation.y=t*.9;c.position.y=4.25+Math.sin(t*2+f.phase)*.08;
  if(c.userData.glow&&camera)c.userData.glow.lookAt(camera.position);
  c.visible=f.alive;
}
// a kill with Apex: judged from above
function apexKill(v){
  hwBeam(v.pos.x,v.y,v.pos.z,0xffd27a,1.4,.7);hwBeam(v.pos.x,v.y,v.pos.z,0xffffff,.6,.5);
  ringBurst(v.pos.x,v.y+.3,v.pos.z,QUAL>1?40:18,16,0xffd27a,1.6,.7);
  burst(v.pos.x,v.y+2,v.pos.z,QUAL>1?50:20,14,0xfff0c0,1.8,.8,-3);
  try{tone(880,1760,.5,"sine",.1);tone(1320,2640,.6,"sine",.06);noiseHit(.5,.25,900);tone(70,35,.8,"sine",.25);}catch(e){}
}
// a shot's tracer: from the muzzle straight out along the aim, with a flash,
// a ring of smoke and a spent case flicked out of the side
function gunTracer(f,tx,ty,tz){
  var tip=f.swordTip(),yaw=f.isPlayer?camYaw:(f.aimYaw!=null?f.aimYaw:f.yaw);
  if(tx===undefined){tx=tip.x+Math.sin(yaw)*40;ty=tip.y;tz=tip.z+Math.cos(yaw)*40;}
  var dx=tx-tip.x,dy=ty-tip.y,dz=tz-tip.z,L=Math.sqrt(dx*dx+dy*dy+dz*dz)||1,n=Math.min(40,Math.ceil(L/1.2));
  for(var i=0;i<n;i++){var k=i/n;spark(tip.x+dx*k,tip.y+dy*k,tip.z+dz*k,0,0,0,1,.85-k*.3,.4,.5-k*.2,.14+k*.05,0);}
  burst(tip.x,tip.y,tip.z,QUAL>1?16:8,10,0xffe0a0,1.4,.14,0);
  ringBurst(tip.x,tip.y,tip.z,10,3,0x9a9aa4,.9,.5);
  spark(tip.x,tip.y,tip.z,Math.cos(yaw)*4,5,-Math.sin(yaw)*4,.9,.75,.3,.3,.6,-12);
}

