// BERT SAMPSOON -- a true classic: the scarlet speedster. A red box helmet
// with a yellow visor band, a lightning emblem on each side of the head and an
// antenna on top; the emblem on the chest, a bolt down the back, and lit
// stripes and bolts round the arms and legs
SIG_SKIN.flash=function(f,g,sk,box,glowM,darkM,bodyM){
  var i,sd,red=new THREE.MeshPhongMaterial({color:0xb81414,shininess:60,emissive:0x2a0000,emissiveIntensity:.4});
  var red2=new THREE.MeshPhongMaterial({color:0x8a0c0c,shininess:40});
  var gold=new THREE.MeshBasicMaterial({color:0xffcc2a}),white=new THREE.MeshBasicMaterial({color:0xfff4d8});
  function bolt(par,x,y,z,s,ry,mat){         // a zig-zag bolt made of three bars
    var b=new THREE.Group();b.position.set(x,y,z);b.rotation.y=ry||0;b.scale.setScalar(s);par.add(b);
    var p=[[.06,.16,-.5],[0,0,.9],[-.06,-.16,-.5]];
    for(var k=0;k<3;k++){var q=new THREE.Mesh(GEO.box,mat||gold);q.scale.set(.34,.07,.03);q.position.set(p[k][0],p[k][1],0);q.rotation.z=p[k][2];b.add(q);}
    return b;
  }
  function emblem(x,y,z,ry,r){               // a gold ring on white, with a bolt through it
    var e=new THREE.Group();e.position.set(x,y,z);e.rotation.y=ry;g.add(e);
    var d=new THREE.Mesh(GEO.cyl,white);d.scale.set(r,.03,r);d.rotation.x=Math.PI/2;e.add(d);
    var rg=new THREE.Mesh(new THREE.TorusGeometry(r*.95,r*.14,6,20),gold);rg.position.z=.02;e.add(rg);
    bolt(e,0,0,.04,r*1.9,0,new THREE.MeshBasicMaterial({color:0xd81a1a}));
    return e;
  }
  box(1.0,.86,.6,0,2.3,0,red);                                   // the suit
  box(1.02,.1,.62,0,1.9,0,gold);                                 // belt
  emblem(0,2.36,.31,0,.26);                                      // the chest emblem
  var bk=bolt(g,0,2.32,-.31,1.3,Math.PI);                        // and a bolt down the back
  // the helmet: a red box, the visor band, emblems on both sides, an antenna
  box(.92,.86,.86,0,2.98,0,red);
  box(.94,.2,.9,0,3.0,0,red2);
  box(.8,.2,.06,0,3.04,.44,gold);                                // the visor band
  for(sd=-1;sd<=1;sd+=2){emblem(sd*.47,3.02,0,sd*Math.PI/2,.17);box(.14,.1,.2,sd*.44,2.72,.3,red2);}
  box(.16,.16,.1,0,3.46,-.3,red2);
  box(.04,.4,.04,0,3.6,.02,gold);                                // antenna
  var ab=new THREE.Mesh(GEO.sphLo,gold);ab.scale.setScalar(.14);ab.position.set(0,3.84,.02);g.add(ab);
  box(.9,.06,.06,0,2.62,.42,red2);                               // the jaw line
  // arms and legs: a gold band and a bolt across each, on the limb itself
  for(sd=0;sd<2;sd++){
    var ar=f.arms[sd],lg=f.legs[sd],s=sd?1:-1;
    [[-.2,.34],[-.78,.3]].forEach(function(b){var q=new THREE.Mesh(GEO.box,gold);q.scale.set(b[1],.06,b[1]);q.position.y=b[0];ar.add(q);});
    var ab2=bolt(ar,s*.15,-.5,0,.55,s*Math.PI/2);ab2.rotation.z=.9;
    [[-.46,.42],[-1.06,.34]].forEach(function(b){var q=new THREE.Mesh(GEO.box,gold);q.scale.set(b[1],.07,b[1]*1.05);q.position.y=b[0];lg.add(q);});
    var lb=bolt(lg,0,-.78,.18,.6,0);lb.rotation.z=1.2;
  }
  f.sig={kind:"flash",ab:ab};
};
