// the per-frame life of the 4.0 skins
var SIG_TICK4={
  blackcat:function(f,s,dt,t){
    var sp=Math.hypot(f.vel.x,f.vel.z);
    for(var i=0;i<s.tail.length;i++){s.tail[i].rotation.z=Math.sin(t*(2+sp*.08)+i*.6+f.phase)*.22;s.tail[i].rotation.x=.12+Math.sin(t*1.3+i)*.05;}
    var tw=(t+f.phase)%4.5<.18;
    s.ears[0].rotation.z=tw?.35:0;s.ears[1].rotation.z=tw?-.2:0;
    var bl=(t*1.3+f.phase)%5<.1;
    s.glow.color.setHex(bl?0x0a0806:0xffd23f);
  },
  ascended:function(f,s,dt,t){
    s.halo.rotation.z=t*.8;
    s.crack.color.setHSL(.13,.9,.78+.18*Math.sin(t*2.4+f.phase));
    // stand still for a moment and you rise a few studs off the floor
    // you never quite touch the floor: a little off it on the move, higher
    // once you stand still for a moment
    // a swing is not moving: it used to count as one, so every block dropped you
    // out of the air and put you back up a second later
    var sp=Math.hypot(f.vel.x,f.vel.z),moving=sp>0.8||!f.grounded;
    if(f.swingT>0){}else s.still=moving?0:s.still+dt;
    var want=s.still>0.7?1.6:(f.grounded?.55:0);
    s.hover+= (want-s.hover)*Math.min(1,dt*(want>s.hover?1.1:6));
    var bob=s.hover>.05?Math.sin(t*1.6+f.phase)*.12*s.hover/1.6:0;
    f.mesh.position.y+=s.hover+bob;
    s.sigil.position.y=-(s.hover+bob)+.06;s.sigil.visible=f.grounded||f.y<.4;
    s.sigil.rotation.y=t*.4;s.star.rotation.z=Math.sin(t*2)*.2;
    // the strips stream out behind you when you move, and drift when you do not
    var lean=clamp(sp/10,0,1);
    for(var i=0;i<s.strips.length;i++){var st=s.strips[i],back=Math.cos(st.userData.a)<0?1:.25;
      st.rotation.x=.06+lean*.95*back+Math.sin(t*3+i*1.7)*(.08+lean*.12);
      st.rotation.z=Math.sin(t*2.3+i)*.1;}
  },
  origami:function(f,s,dt,t){var fl=Math.sin(t*3+f.phase)*.5;s.wings[0].rotation.x=fl;s.wings[1].rotation.x=-fl;s.crane.position.y=2.98+Math.sin(t*1.5)*.03;},
  golem:function(f,s,dt,t){s.rune.color.setHSL(.42,1,.45+.2*Math.sin(t*2+f.phase));},
  prismknight:function(f,s,dt,t){for(var i=0;i<s.crys.length;i++)s.crys[i].emissive.setHSL(((t*.15+i*.13+f.phase)%1),1,.35);},
  "null":function(f,s,dt,t){
    s.halo.rotation.y=t*1.2;s.halo.position.y=3.72+Math.sin(t*2)*.06;
    var gl=((t*3+f.phase)%3.1)<.06;
    s.wire.color.setHex(gl?0xffffff:0x00ffe0);s.halo.position.x=gl?rr(-.1,.1):0;
  },
  pharaoh:function(f,s,dt,t){s.glow.color.setHSL(.5,1,.5+.1*Math.sin(t*3));},
  butcher:function(){}
};
