var dragging=false,rightLook=false;
/* Press a touch early and the swing is held rather than thrown away: it
   connects the moment the ball actually reaches your window. Deliberately
   short -- it forgives a fractionally early press, it does not let you mash. */
var PARRY_BUFFER=0.16;
var LOCK_BLOCKED=false;
function lockPointer(){
  if(touchMode||!SAVE.mouseLock)return false;
  if(document.pointerLockElement===canvas)return true;
  if(!canvas.requestPointerLock){noteLockBlocked();return false;}
  try{
    var r=canvas.requestPointerLock();
    // newer browsers hand back a promise that rejects when the page is not
    // allowed to capture the cursor (a sandboxed embed, for instance)
    if(r&&r.catch)r.catch(function(){noteLockBlocked();});
    return true;
  }catch(err){noteLockBlocked();return false;}
}
// cursor capture refused: carry on quietly, the cursor is hidden while steering instead
function noteLockBlocked(){LOCK_BLOCKED=true;}
// open the game in a tab of its own, where nothing is sandboxing it
function popOut(){
  try{
    var w=window.open(window.location.href,"_blank");
    if(!w)feed("Your browser blocked the pop-out","ko");
  }catch(e){feed("Could not pop out","ko");}
}
function unlockPointer(){
  if(document.pointerLockElement===canvas&&document.exitPointerLock){
    try{document.exitPointerLock();}catch(err){}
  }
}
function pointerLocked(){return document.pointerLockElement===canvas;}
canvas.addEventListener("mousedown",function(e){
  if(e.button===0&&STATE==="playing")tryParry();
  if(e.button===0&&STATE==="venue")rangeSwing();
  if(e.button===2){
    // right button is look: hold it to steer, and it grabs the cursor
    rightLook=true;dragging=true;lockPointer();refreshCursor();
    e.preventDefault();
  } else if(e.button===0){
    dragging=true;            // left-drag still looks, but never grabs the cursor
  }
});
window.addEventListener("mouseup",function(e){
  if(e.button===2){
    rightLook=false;dragging=false;
    if(!shiftLock)unlockPointer();     // shift lock keeps it held
    refreshCursor();
  } else if(e.button===0){dragging=false;}
});
