/* ============================================================
   15. CAMERA + SHOWCASE
   ============================================================ */
function updateCamera(dt){
  var sens=(touchMode?0.0045:0.0027)*SENS;
  camYaw-=lookD.x*sens;
  camPitch-=lookD.y*sens*(SAVE.invertY?-1:1);
  lookD.x=0;lookD.y=0;
  var kx=0,ky=0;
  if(keys.ArrowLeft)kx+=1;
  if(keys.ArrowRight)kx-=1;
  if(keys.ArrowUp)ky+=1;
  if(keys.ArrowDown)ky-=1;
  camYaw+=kx*2.7*dt*SENS;
  camPitch+=ky*1.5*dt*SENS;
  camPitch=clamp(camPitch,-0.85,0.5);
  if(STATE==="menu"){updateShowcase(dt);return;}
  var f=camFocus();
  camLook.x=damp(camLook.x,f?f.pos.x:0,22,dt);
  camLook.y=damp(camLook.y,(f?f.y:0)+2.6,13,dt);
  camLook.z=damp(camLook.z,f?f.pos.z:0,22,dt);
  var want=(f&&ballOn(f))?15:13;
  camDist=damp(camDist,want,4,dt);
  var cy=Math.cos(camPitch);
  // shift lock swings the view over the right shoulder and slides the look target
  // with it, so your fighter sits left of centre and the dot is the aim point
  shoulder=damp(shoulder,shiftLock?SHOULDER:0,12,dt);
  var srx=-Math.cos(camYaw)*shoulder, srz=Math.sin(camYaw)*shoulder;
  var px=camLook.x+srx-Math.sin(camYaw)*cy*camDist;
  var py=Math.max(1.6,camLook.y+(Math.sin(-camPitch)+0.42)*camDist);
  var pz=camLook.z+srz-Math.cos(camYaw)*cy*camDist;
  /* The camera used to be damped toward a point that was itself damped toward
     you -- two filters in series. Strafing pushed you off the middle of the
     screen and the whole view swung sideways to catch up, and a view that
     rotates while you run is what reads as the screen tilting. camLook already
     smooths the follow; the camera now sits rigidly on its orbit around that,
     so you stay centred and the horizon stops swinging. */
  camera.position.set(px,py,pz);
  camera.lookAt(camLook.x+srx,camLook.y,camLook.z+srz);
  if(camShake>0){camera.position.x+=rr(-1,1)*camShake;camera.position.y+=rr(-1,1)*camShake*0.6;camShake=Math.max(0,camShake-dt*3);}
  if(skyDome)skyDome.position.copy(camera.position);
}
/* Who you watch once you are out. In 2v2 it is your surviving partner. In a
   hosted free-for-all it is whoever killed you -- and if they go down too, it
   follows whoever killed THEM, so the camera walks the chain to whoever is
   still standing rather than staring at a corpse. */
function spectateChain(){
  var seen={},f=player&&player.killedBy;
  for(var hop=0;hop<8&&f;hop++){
    if(f.alive)return f;
    var key=f.netId||f.name||("i"+hop);
    if(seen[key])break;
    seen[key]=1;
    f=f.killedBy;
  }
  var all=livingFighters(false);
  return all.length?all[0]:null;
}
function camFocus(){
  if(player&&player.alive)return player;
  if(MODE.teams){
    var all=livingFighters(false);
    for(var i=0;i<all.length;i++)if(all[i].team===0)return all[i];
  }
  if(NET.on){
    var w=spectateChain();
    if(w)return w;
  }
  return player;
}
var SPEC={on:false,who:"",hid:false};
function updateSpectate(){
  var el=$("spechud");
  if(!el)return;
  if(!SPEC.on||STATE!=="playing"){
    el.style.display="none";
    if(SPEC.hid){SPEC.hid=false;$("slots").style.display="";}
    return;
  }
  var w=spectateChain();
  var nm=w?w.name:"";
  if(nm!==SPEC.who){SPEC.who=nm;$("specWho").textContent=nm||"NOBODY";}
  el.style.display="block";
  // nothing left to press, so the buttons go rather than sitting there dead
  if(nm&&!SPEC.hid){SPEC.hid=true;$("slots").style.display="none";}
}
function startSpectating(){
  SPEC.on=true;
  var w=spectateChain();
  SPEC.who=w?w.name:"";
  if(w&&player&&player.killedBy===w)
    flashWarn("SPECTATING "+w.name.toUpperCase(),1.6,"#8fd8ff");
  else if(w)flashWarn("SPECTATING "+w.name.toUpperCase(),1.4,"#8fd8ff");
}
function stopSpectating(){SPEC.on=false;SPEC.who="";}
function refreshShowcase(){
  if(showcase){dropShell(showcase);scene.remove(showcase.mesh);showcase=null;}
  /* The turning figure belongs to the old menu screen only. Built from the
     lobby -- after a purchase, a code, the casino or a cloud sync -- it stood
     frozen in the middle of the room with nothing to animate or remove it:
     the glitched figure on the podium. */
  if(STATE!=="menu")return;
  showcase=new Fighter({name:"YOU",isPlayer:true,x:0,z:0,
    sword:SAVE.eqSword,ability:SAVE.eqAbil,skinDef:skinById(SAVE.eqSkin)});
  showcase.tag.visible=false;
}
function updateShowcase(dt){
  if(!showcase)refreshShowcase();
  showT+=dt;
  showcase.yaw=showT*0.42;
  showcase.update(dt,showT);
  if(showcase.swingT<=0&&Math.random()<dt*0.45)showcase.swing();
  var a=showT*0.13;
  var lateral=(window.innerWidth>760)?3.6:0;
  var r=11.5;
  camera.position.set(Math.sin(a)*r-Math.cos(a)*lateral,5.6,Math.cos(a)*r+Math.sin(a)*lateral);
  camera.lookAt(-Math.cos(a)*lateral*0.6,2.1,Math.sin(a)*lateral*0.6);
  if(skyDome)skyDome.position.copy(camera.position);
}

