  var it=limItem(tab,id);
  if(!on||!it||!limEligible(it))return {ok:false,why:"That is not on the shelf any more."};
  var d=shopData(tab);
  if(d.own[id])return {ok:false,why:"You already own "+it.name+"."};
  var cost=limPrice(it);
  if(SAVE.yen<cost)return {ok:false,why:"Not enough yen: "+it.name+" is "+cost.toLocaleString()+", you have "+SAVE.yen.toLocaleString()+"."};
  SAVE.yen-=cost;
