  if(fL>0&&!(freeSpinOk()&&chestGrade==="legendary"))fTxt.push("You have "+fL+" free LEGENDARY+ spin"+(fL>1?"s":"")+" from the login calendar. Pick LEGENDARY+ and 1\u00d7 to use one.");
