/* ============================================================
   17. HUD TICK
   ============================================================ */
function updateHUD(dt){
  var top=1;
  for(var i=0;i<balls.length;i++)if(balls[i].mult>top)top=balls[i].mult;
  var sp=(Math.round(top*10)/10).toFixed(1)+"x";
  if(hudC.sp!==sp){$("spdN").textContent=sp;hudC.sp=sp;}
  var b=player&&player.alive?ballOn(player):null;
  var lock=$("lockring");
  if(b){
    var t=clamp(tti(b),0,1.2);
    var op=Math.round((0.12+(1-t/1.2)*0.8)*20)/20;   // quantised: skips most writes
    if(hudC.lock!==op){lock.style.opacity=String(op);hudC.lock=op;}
    if(gameT-lastTick>0.16&&t<1.0){sfx("tick");lastTick=gameT;}
  } else if(hudC.lock!==0){lock.style.opacity="0";hudC.lock=0;}
  if(player){
    var a=abilById(player.ability);
    var af=a.passive?0:clamp(player.abilCd/Math.max(0.01,a.cd),0,1);
    if(RIFT.phase==="duel"&&player===RIFT.caster)af=0;
    riftHud();
    var afq=Math.round(af*20);
    if(hudC.af!==afq){
      $("slotAbil").querySelector(".cd").style.height=(af*100)+"%";
      $("slotAbil").classList.toggle("ready",af<=0&&!a.passive);
      hudC.af=afq;
    }
    var pf=clamp(player.blockCd/BLOCK.cd,0,1);
    var pfq=Math.round(pf*20)+(player.blockT>0?100:0);
    if(hudC.pf!==pfq){
      $("slotParry").querySelector(".cd").style.height=(pf*100)+"%";
      $("slotParry").classList.toggle("ready",pf<=0);
      $("slotParry").classList.toggle("blocking",player.blockT>0);
      hudC.pf=pfq;
    }
  }
}

/* ============================================================
   18. MAIN LOOP
   ============================================================ */
var last=0,frames=0,fpsAcc=0;
function frame(ts){
  window.requestAnimationFrame(frame);
  if(!last)last=ts;
  var dt=Math.min((ts-last)/1000,0.034);
  last=ts;
  if(STATE==="boot"||paused)return;
  FRAME_N++;
  // The big centre banner ("3", "GO", "ELIMINATED") used to expire inside
  // updateHUD, which only runs during a match -- so quitting to the lobby while
  // one was up left it frozen on screen for good. Time it out here, whatever
  // state we are in.
  if(warnT>0){warnT-=dt;if(warnT<=0)$("warn").classList.remove("on");}
  limitedTick(dt);
  if(WHITE_T>0||WHITE_SHOWN){
    WHITE_T=Math.max(0,WHITE_T-dt);
    var wk=WHITE_T/WHITE_MAX;                   // 1 -> 0 over the flash
    var wo=wk>0.4?1:wk/0.4;                      // full white, then a fade
    if(STATE!=="playing"&&STATE!=="countdown"&&STATE!=="over"){wo=0;WHITE_T=0;}
    $("whiteout").style.opacity=wo.toFixed(3);
    WHITE_SHOWN=wo>0;
  }
  gameT+=dt;
  slowmoT=Math.max(0,slowmoT-dt);
  var worldDt=slowmoT>0?dt*0.4:dt;
  if(STATE==="playing"&&gameT>75&&!hudC.sudden){
    hudC.sudden=true;flashWarn("SUDDEN DEATH",1.2,"#ff3ca8");
    feed("Sudden death \u2014 the parry window is closing","ko");
  }
  if(STATE==="countdown"){
    countdown-=dt;
    var n=Math.ceil(countdown-0.2);
    if(n>0&&hudC.cd!==n){flashWarn(String(n),0.9,"#35e8ff");sfx("tick");hudC.cd=n;}
    if(countdown<=0.2&&hudC.cd!==0){flashWarn("GO",0.7,"#6bffb0");hudC.cd=0;}
    if(countdown<=0){
      STATE="playing";
      // A guest does not launch its own ball: the host's first snapshot brings
      // it into play. Launching locally put a second, made-up ball in the air
      // for the first moments of every round, which then vanished or jumped.
      if(!(NET.on&&!NET.isHost))for(var k=0;k<balls.length;k++)launchBall(balls[k],null);
    }
  }
  // the lobby's "F / TAP -- CASUAL" prompt belongs to the lobby only; walking
  // onto a pad and starting a match from it used to leave it up all game
  if(STATE!=="venue"&&hudC.zone!==null){$("zonePrompt").classList.remove("on");hudC.zone=null;nearZone=null;}
  if(STATE==="menu"){
    updateCamera(dt);updateParticles(dt);renderer.render(scene,camera);
    return;
  }
  if(STATE==="venue"){
    updateVenue(dt,gameT);
    updateParticles(dt);
    updateCamera(dt);
    renderer.render(scene,camera);
    return;
  }
  if(STATE==="countdown"||STATE==="playing"||STATE==="over"){
    if(player&&STATE!=="over"&&!player.isRemote)updatePlayer(dt);
    resolveParryBuffer(dt);
    for(var i=0;i<fighters.length;i++){
      var f=fighters[i];
      if(f.isRemote)netUpdateRemote(f,dt);
      // bots walk about during the countdown too, like you can
      else if(!f.isPlayer)updateBot(f,worldDt);
      f.update(f.isPlayer?dt:worldDt,gameT);
    }
    riftTick(worldDt,gameT);
    if(NET.on)netTick(dt);
    // sweep dead decoys out
    for(i=fighters.length-1;i>=0;i--)
      if(fighters[i].decoy&&!fighters[i].alive&&fighters[i].mesh.scale.x<0.05){
        removeFighter(fighters[i]);
      }
    if(STATE==="playing"){
      updateCats(worldDt,gameT);
      updateDrones(worldDt);
      updateArenaAnim(worldDt,gameT);
      specialsTick(worldDt);
      v4Tick(worldDt);
      trickTick(worldDt);
      ANY_ARMED=false;
      for(i=0;i<fighters.length;i++)if(fighters[i].alive&&fighters[i].catchArmT>0){ANY_ARMED=true;break;}
      for(i=0;i<balls.length;i++){
        // the rift: nothing moves while it opens or closes, and only one ball duels
        if(RIFT.phase&&(RIFT.phase!=="duel"||i>0))continue;
        updateBall(balls[i],worldDt,gameT);
        // (a guest's ball runs its effect layer inside netCoastBall)
        if(balls[i].active&&!(NET.on&&!NET.isHost)){paintBall(balls[i]);ballFx(balls[i],worldDt);}
        ballHitboxDebug(balls[i]);
        updateHoldLabel(balls[i]);
      }
      // in 2v2 your ally plays on after you die, so only solo modes end on your death
      if(NET.on&&NET.isHost)netResolvePending();
      /* Your own death used to end the round in every non-team mode. Over the
         network that ended it for EVERYONE -- and since the host is the one
         simulating, the host dying killed the match for the whole lobby. A
         networked round now ends when the host's checkEnd says only one side is
         left standing, and the dead watch the rest of it. */
      if(player&&!player.alive&&!hudC.dead&&!MODE.teams){
        hudC.dead=true;
        if(NET.on){startSpectating();if(NET.isHost)checkEnd();}
        else setTimeout(endRound,900);
      }
    }
    setAlive();
  }
  updateParticles(dt);
  updateCamera(dt);
  updateHUD(dt);
  updateSpectate();
  if(bandMat){
    bandMat.map.offset.x=(gameT*0.15)%1;
    var hunted=false;
    for(i=0;i<balls.length;i++)if(balls[i].active&&ballIsOnPlayer(balls[i]))hunted=true;
    bandMat.color.setHex(hunted?0xff2a2a:CURMAP.accentA);
  }
  for(i=0;i<ringMeshes.length;i++)
    ringMeshes[i].material.opacity=0.24+Math.sin(gameT*2+i)*0.16;
  // turned to face the camera itself (to its yaw they faced away, and were culled)
  var asc=arena.scale.x||1;
  for(i=0;i<BILLBOARDS.length;i++){var bl=BILLBOARDS[i];
    bl.rotation.y=Math.atan2(camera.position.x-bl.position.x*asc-arena.position.x,camera.position.z-bl.position.z*asc-arena.position.z);}
  var fc=camFocus();
  sun.target.position.set(fc?fc.pos.x:0,0,fc?fc.pos.z:0);
  sun.position.set((fc?fc.pos.x:0)+38,62,(fc?fc.pos.z:0)+24);
  sun.target.updateMatrixWorld();
  frames++;fpsAcc+=dt;
  if(fpsAcc>1){$("fps").textContent=frames+" FPS";frames=0;fpsAcc=0;}
  renderer.render(scene,camera);
}


