var BALL_SWATCHES=["#9aa3ad","#ffffff","#35e8ff","#6bffb0","#ffd23f","#ff8a3c",
                   "#ff3ca8","#b14aff","#4a6cff","#1a1a22"];
function ballColorHex(){
  var c=SAVE.ballColor||"#9aa3ad";
  return parseInt(c.replace("#",""),16)||0x9aa3ad;
}
function applyBallColor(){
  for(var i=0;i<balls.length;i++){
    var b=balls[i];
    if(b.core&&b.core.material)b.core.material.color.setHex(ballColorHex());
  }
}
function setTog(id,on){
  var el=$(id);if(!el)return;
  el.textContent=on?"ON":"OFF";
  el.classList.toggle("on",!!on);
}
function buildSwatches(){
  var host=$("sBallSw");if(!host)return;
  host.innerHTML="";
  BALL_SWATCHES.forEach(function(c){
    var i=document.createElement("i");
    i.style.background=c;
    i.className=(String(SAVE.ballColor).toLowerCase()===c?"sel":"");
    i.addEventListener("click",function(){
      SAVE.ballColor=c;writeSave();applyBallColor();buildSwatches();
      var cu=$("sBallCustom");if(cu)cu.value=c;
      sfx("tick");
    });
    host.appendChild(i);
  });
}
function refreshSettings(){
  var v;
  v=$("sSens"); if(v){v.value=SAVE.sens;$("sSensV").textContent=(+SAVE.sens).toFixed(2);}
  v=$("sFov");  if(v){v.value=SAVE.fov;$("sFovV").textContent=SAVE.fov;}
  v=$("sDist"); if(v){v.value=SAVE.camDist;$("sDistV").textContent=SAVE.camDist;}
  v=$("sMusicVol");if(v){v.value=SAVE.musicVol;$("sMusicV").textContent=Math.round(SAVE.musicVol*100)+"%";}
  v=$("sSfxVol");  if(v){v.value=SAVE.sfxVol;$("sSfxV").textContent=Math.round(SAVE.sfxVol*100)+"%";}
  v=$("sMusicUrl");if(v)v.value=SAVE.musicUrl||"";
  v=$("sBallCustom");if(v)v.value=SAVE.ballColor||"#9aa3ad";
  setTog("sInvert",SAVE.invertY); setTog("sShift",shiftLock);
  setTog("sMouseLock",SAVE.mouseLock); setTog("sBallGlow",SAVE.ballGlow);
  setTog("sMusicOn",SAVE.musicOn); setTog("sFps",SAVE.showFps); setTog("sHitbox",!!SAVE.showHitbox);
  setTog("sTags",SAVE.nameTags); setTog("sFeed",SAVE.feedOn);
  var qb=$("sQual");
  if(qb)for(var i=0;i<qb.children.length;i++)
    qb.children[i].classList.toggle("sel",+qb.children[i].getAttribute("data-q")===SAVE.qual);
  buildSwatches();
  $("fps").style.display=SAVE.showFps?"":"none";
}
