function applyFov(v){
  v=clamp(v|0,55,100);
  SAVE.fov=v;
  camera.fov=v;
  camera.updateProjectionMatrix();
  var a=$("fovv1"),b=$("fovv2");
  if(a)a.textContent=v;
  if(b)b.textContent=v;
  writeSave();
}
