function applyQuality(q){
  QUAL=q;
  SAVE.qual=q;
  renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,q===0?1:(q===1?1.4:2)));
  sun.castShadow=q>0;
  if(sun.shadow.map){sun.shadow.map.dispose();sun.shadow.map=null;}
  sun.shadow.mapSize.set(q===2?2048:1024,q===2?2048:1024);
  scene.fog.far=q===0?170:(q===1?260:340);
  resize();
}
