$("chestSpin").addEventListener("click",function(){
  if(REEL.busy||shopTab==="limited")return;
  var res=$("chestResult"),total=chestUnitCost(shopTab,chestGrade)*chestQty,free=freeSpinOk();
  if(!free&&SAVE.coins<total){res.innerHTML="<span style='color:#ffa8e0'>Not enough coins.</span>";return;}
  if(econOn()){
    // signed in: the server opens the chests, and the reel shows what it rolled
    var tabS=shopTab,dS=shopData(tabS);REEL.busy=true;
    res.innerHTML="<span style='opacity:.6'>Opening\u2026</span>";
    econAct([{k:"chest",tab:tabS,grade:chestGrade,n:chestQty,free:free}],function(err,rs){
      REEL.busy=false;
      var r0=rs&&rs[0];
      if(err||!r0||!r0.ok){res.innerHTML="<span style='color:#ffa8e0'>"+((r0&&r0.why)||econErr(err))+"</span>";return;}
      var got=[],best=null;
      r0.res.won.forEach(function(w){var it=findId(dS.list,w.id);if(!it)return;var c={};for(var k in it)c[k]=it[k];
        c._dupe=!!w.dupe;c._refund=w.refund||0;got.push(c);
        if(!c._dupe&&(!best||RARORDER.indexOf(c.rarity)<RARORDER.indexOf(best.rarity)))best=c;});
      if(best){SAVE[dS.eq]=best.id;writeSave();}
      if(got.length)chestShow(got,tabS,res);
    });
    return;
  }
  var wins=spinChests(shopTab,chestGrade,chestQty,free);
  if(!wins)return;
  chestShow(wins,shopTab,res);
});
function chestShow(wins,tab,res){
  // the reel lands on the best thing you got
  var show=wins[0];
  for(var i=1;i<wins.length;i++)if(RARORDER.indexOf(wins[i].rarity)<RARORDER.indexOf(show.rarity))show=wins[i];
  REEL.busy=true;
  $("reelBox").style.display="block";
  res.innerHTML="<span style='opacity:.6'>Rolling"+(wins.length>1?" "+wins.length+" chests":"")+"\u2026</span>";
  runReel(show,tab,function(){
    REEL.busy=false;
    var rar=RARITY[show.rarity||"common"];
    sfx((rar.n==="MYTHIC"||rar.n==="LEGENDARY")?"rank":"coin");
    res.innerHTML=chestHaulHtml(wins,tab);
    buildShop();updateChips();refreshShowcase();
    // on a small screen the haul lands below the fold: bring it up
    try{if(res.scrollIntoView)res.scrollIntoView({block:"nearest",behavior:"smooth"});}catch(e){}
  },chestGrade);
}
