/* What each redeem code gives. The codes themselves are on the server --
   anyone can read this page, so a code written here was a code anyone could
   find. The server is sent what was typed and answers with the name of the
   reward; the reward is handed out here, where the items are. */
var REWARDS={
  all:function(){
    // everything except ULTRAs (their own code only) and Halloween Pass items (the pass only)
    for(var i=0;i<SWORDS.length;i++)if(!SWORDS[i].ultra&&!SWORDS[i].pass)SAVE.swords[SWORDS[i].id]=1;
    for(i=0;i<ABILITIES.length;i++)if(!ABILITIES[i].ultra&&!ABILITIES[i].pass)SAVE.abils[ABILITIES[i].id]=1;
    for(i=0;i<SKINS.length;i++)if(!SKINS[i].ultra&&!SKINS[i].pass)SAVE.skins[SKINS[i].id]=1;
    SAVE.rp=Math.max(SAVE.rp,RANKS[RANKS.length-1].rp);
    SAVE.coins+=250000;
    SAVE.yen+=28000;
    return "Everything unlocked, Omega rank, +250,000 coins and 28,000 yen. Go wild.";
  },
  threeblades:function(){
    // must be the BLADE pool. With no argument this fell through to whatever
    // shop tab you last opened, so the code could write ability ids into your
    // sword collection -- three names in the message, nothing usable, code spent.
    var pool=chestPool("sword").filter(function(w){return !SAVE.swords[w.id];});
    var got=[];
    for(var i=0;i<3&&pool.length;i++){
      var n=Math.floor(Math.random()*pool.length);
      var w=pool.splice(n,1)[0];       // no repeats inside one redeem
      SAVE.swords[w.id]=1;got.push(w.name);
    }
    return got.length?("Unlocked: "+got.join(", ")):"You already own every blade.";
  },
  coins5000:function(){SAVE.coins+=5000;return "+5,000 coins.";},
  stdslash:function(){
    SAVE.abils.stdslash=1;SAVE.eqAbil="stdslash";
    return "Santi's STD Slash unlocked, and equipped.";
  },
  bloodrift:function(){
    SAVE.abils.bloodrift=1;
    return "BLOOD RIFT unlocked. ULTRA. One use per game: look at a player and cast it.";
  },
  cruz:function(){
    SAVE.abils.cruz=1;SAVE.eqAbil="cruz";
    return "Spirit of Cruz unlocked, and equipped.";
  },
  wendigo:function(){
    SAVE.swords.wendigo=1;SAVE.eqSword="wendigo";
    return "WENDIGO KATANA unlocked, and equipped. UNRELEASED.";
  }
};
$("pfRedeem").addEventListener("click",function(){
  var box=$("redeemBox");
  var code=((box&&box.value)||"").trim().toLowerCase().replace(/[^a-z0-9]/g,"");
  if(!code){$("pfMsg").textContent="Type a code first.";return;}
  SAVE.redeemed=SAVE.redeemed||{};
  if(SAVE.redeemed[code]){
    $("pfMsg").innerHTML="<span style='color:#ffd23f'>You have already redeemed that one.</span>";return;
  }
  if(REDEEMING)return;
  var say=function(t,c){$("pfMsg").innerHTML="<span style='color:"+(c||"#ffa8e0")+"'>"+t+"</span>";};
  REDEEMING=true;say("Checking...","#cfe2ff");
  cloudPost("/redeem",econOn()?{code:code,token:CLOUD.tok}:{code:code}).then(function(r){
    REDEEMING=false;
    if(r.status===403&&r.j&&r.j.error==="banned"){cloudBanned(r.j.why);return;}
    // signed in: the server put it on the account (once), and sends the account back
    if(r.status===200&&r.j&&r.j.res){
      var r0=r.j.res[0]||{},sv=r.j.save||{};
      if((r.j.rev|0)>CLOUD.rev)CLOUD.rev=r.j.rev|0;
      econTake(sv);
      if(r0.already){say("You have already redeemed that one.","#ffd23f");return;}
      if(!r0.ok){say("That code does not work.");return;}
      // a code that equips what it gives
      if(sv.eqSword&&SAVE.swords[sv.eqSword])SAVE.eqSword=sv.eqSword;
      if(sv.eqAbil&&SAVE.abils[sv.eqAbil])SAVE.eqAbil=sv.eqAbil;
      writeSave();refreshCoins();updateChips();refreshShowcase();renderProfile();
      if(box)box.value="";
      sfx("rank");
      say(typeof r0.msg==="string"?r0.msg:("Unlocked: "+((r0.msg&&r0.msg.unlocked)||[]).map(function(id){return swordById(id).name;}).join(", ")),"#b8ff8f");
      return;
    }
    var fn=r.status===200&&r.j.reward&&REWARDS.hasOwnProperty(r.j.reward)?REWARDS[r.j.reward]:null;
    if(r.status===429){say("Too many tries. Wait a minute and try again.");return;}
    if(r.status===404&&r.j.error){say("That code does not work.");return;}
    if(!fn){say("Codes could not be checked just now. Try again in a moment.");return;}
    if(SAVE.redeemed[code]){say("You have already redeemed that one.","#ffd23f");return;}
    var msg=fn();
    SAVE.redeemed[code]=1;
    grantRankRewards(true);
    writeSave();refreshCoins();updateChips();refreshShowcase();
    renderProfile();
    if(box)box.value="";
    sfx("rank");
    say(msg,"#b8ff8f");
  },function(){REDEEMING=false;say("Could not reach the server to check that code. Check your connection.");});
});
var REDEEMING=false;
$("pfWipe").addEventListener("click",function(){
  if(window.confirm&&!window.confirm(cloudOn()?"Wipe all progress on this device? You will be signed out of Google first, so the save on your account is kept.":"Wipe all progress on this device?"))return;
  if(cloudOn())cloudSignOut();
  var kept={};
  for(var i=0;i<KEEP_ON_WIPE.length;i++){
    var k=KEEP_ON_WIPE[i];
    if(SAVE[k]!==undefined)kept[k]=SAVE[k];
  }
  SAVE=defaultSave();
  for(var k2 in kept)SAVE[k2]=kept[k2];
  // a wipe must leave the casino in a clean state too, or a half-played hand
  // settles against the new balance
  BJ.inHand=false;BJ.you=[];BJ.dealer=[];BJ.doubled=false;BJ.stake=0;
  writeSave();refreshCoins();updateChips();refreshShowcase();
  renderProfile();
  $("pfMsg").textContent="Progress reset.";
});
