function runStep(i){
  if(i>=STEPS.length){
    $("loadfill").style.width="100%";
    $("loadtxt").textContent="READY";
    refreshCoins();
    setTimeout(function(){
      if(SAVE.seenVersion!==VERSION)showScreen("update");
      else enterLobby();
    },200);
    return;
  }
  $("loadtxt").textContent=STEPS[i][0];
  $("loadfill").style.width=Math.round((i/STEPS.length)*100)+"%";
  setTimeout(function(){
    try{STEPS[i][1]();}
    catch(err){$("loadtxt").textContent="ERROR: "+err.message;return;}
    runStep(i+1);
  },30);
}
